(window.GIM_TS=window.GIM_TS||{})["Kiddushin.6"]={"from":144,"a":[["\u0003וניחזי זוזי ממאן נקט\u0004 \u0005[ונראה\u0006 את \u0005הכסף ממי לקח]?\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דנקט מתרוייהו\u0004 \u0005[שלקח משניהם]\u0006 \u0003ואמר\u0004 המוכר: \u0003חד מדעתאי\u0004 \u0005[אחד\u0006 קיבלתי \u0005מדעתי],\u0006 שרציתי למכור לו \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 נתן לי \u0003בעל כורחי,\u0004 שלא רציתי לקבל ממנו. \u0003ולא ידיע\u0004 \u0005[ידוע]\u0006 לבית דין \u0003הי\u0004 \u0005[איזה]\u0006 \u0003מדעתו והי\u0004 \u0005[ואיזה]\u0006 \u0003לא מדעתו,\u0004 ובזה אין אנו סומכים על עדותו ממי קיבל בעל כרחו.","וממשיכה הברייתא, וכן \u0003נאמן\u0004 ה\u0003דיין לומר: לזה זכיתי ולזה חייבתי. במה דברים אמורים\u0004 — \u0003שבעלי דינים\u0004 עדיין \u0003עומדים לפניו, אבל\u0004 אם \u0003אין בעלי דינים עומדים לפניו,\u0004 אלא הלכו להם — \u0003אינו נאמן.\u0004 ושואלים: \u0003וניחזי זכותא מאן נקיט\u0004 \u0005[ונראה\u0006 את \u0005כתב הזכות, מי מחזיק\u0006 בו\u0005]?\u0006 ולשם מה צריך את נאמנותו של הדיין!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דקריע זכותייהו\u0004 \u0005[שנקרעו כתבי הזכויות שלהם]\u0006 ואי אפשר לברר מתוכם. ושואלים: אם כן \u0003וניהדר ונידיינינהו\u0004 \u0005[ויחזור וידון אותם]\u0006 שנית! ומשיבים: שהיה זה \u0003בשודא דדייני\u0004 \u0005[בהכרעת הדיינים],\u0006 שיש מקרים שבהם אין פסק הדין תלוי אלא בהכרעת הדיינים שמחליטים לפי הרגשתם. ובמקרה זה אין ודאות שבפעם השניה יחליטו כבראשונה.","ועוד בענין נאמנות על הבכור, \u0003אמר רב נחמן: שלשה נאמנין על הבכור, אלו הן: חיה\u0004 (המיילדת), \u0003אביו, ואמו. חיה\u0004 נאמנת רק \u0003לאלתר\u0004 (מיד), \u0003אמו\u0004 נאמנת \u0003כל שבעה\u0004 ימים ראשונים ללידתו, \u0003אביו\u0004 נאמן \u0003לעולם. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \"כי את הבכור... \u0003יכיר\u0004 לתת לו פי שניים\" (דברים כא, יז), ואמרו: \u0003יכירנו לאחרים.\u0004 כלומר, הוא נאמן לומר לאחרים שזה בכורו.","\u0003מכאן אמר ר' יהודה: נאמן אדם לומר \"זה בני בכור\". וכשם שנאמן לומר \"זה בני בכור\" כך נאמן לומר\u0004 על בנו \u0003\"זה בן גרושה\",\u0004 או \u0003\"זה בן חלוצה\". וחכמים אומרים:\u0004 בזה \u0003אינו נאמן,\u0004 אלא לבכורה בלבד.","שנינו במשנה ש\u0003אבא שאול היה קורא לשתוקי \"בדוקי\".\u0004 שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בדוקי\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שבודקין את אמו ו\u0004היא \u0003אומרת:\u0004 \u0003לכשר נבעלתי,\u0004 ואז \u0003נאמנת,\u0004 ואם כן הלכה זו \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כ\u0004שיטת \u0003רבן גמליאל\u0004 היא, ואולם \u0003תנינא חדא זימנא\u0004 \u0005[\u0006כבר \u0005שנינו\u0006 דבר זה \u0005פעם אחת]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היתה\u0004 אשה פנויה \u0003מעוברת, ואמרו לה: מה טיבו של עובר זה? אמרה להם: מאיש פלוני\u0004 שנבעלתי לו \u0003וכהן הוא. רבן גמליאל ור' אליעזר אומרים: נאמנת, ור' יהושע אומר: לא מפיה אנו חיין\u0004 ואין סומכים עליה. \u0003ואמר רב יהודה, אמר שמואל: הלכה כרבן גמליאל.\u0004 ומה הוסיף איפוא אבא שאול בדבריו?","ומשיבים: בכל זאת נצרכו דברי אבא שאול, משום ש\u0003חדא\u0004 \u0005[\u0006הלכה \u0005אחת]\u0006 נאמרה כדי \u0003להכשיר בה,\u0004 אותה עצמה, שלא תיחשב כנבעלת לפסול ושהיא עצמה כשירה לכהונה, \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003להכשיר בבתה,\u0004 שאם נולדה לה בת, אף היא נחשבת לכשירה על פי דברי האם, ומותרת להינשא לכהונה. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003לדברי המכשיר בה\u0004 וסומך על דבריה — \u0003פוסל בבתה\u0004 שאין נאמנותה מספיקה להכשיר גם את בתה הנולדת לה, שאין לה חזקת כשרות, ואם כן יש חידוש בדבר שכשאמרה לכשר נבעלתי נאמנת גם על בתה.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003לדברי המכשיר בה מכשיר\u0004 גם \u0003בבתה,\u0004 לפי זה \u0003אבא שאול מאי אתא לאשמועינן\u0004 \u0005[מה בא להשמיענו]?\u0006 הרי כבר ידוע הדבר!","ומשיבים: ההלכה של \u0003אבא שאול עדיפא\u0004 ומרחיקה לכת יותר \u0003מ\u0004זו של \u0003רבן גמליאל. דאי מהתם הוה אמינא\u0004 \u0005[שאילו משם\u0006 בלבד, ענין הפנויה, \u0005הייתי אומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר ש\u0003רוב כשרין\u0004 הם \u0003אצלה,\u0004 כגון שרוב אנשי העיר כשרים לקהל וראויים להשיא בנותיהם לכהונה, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003רוב פסולין אצלה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תהיה נאמנת לומר שנבעלה לכשר, ולכן \u0003צריכא\u0004 \u0005[צריכה]\u0006 הלכה זו של אבא שאול להיאמר גם ברוב פסולים. \u0003אמר רבא: הלכה כאבא שאול.\u0004","\u0003כל האסורין לבא בקהל\u0004 — \u0003מותרים לבא זה בזה. ר' יהודה אוסר\u0004 להם להתחתן אלא מבני אותו סוג של פסול.","\u0003ר' אליעזר אומר: ודאן בודאן\u0004 \u0005[וודאים בוודאים],\u0006 כלומר, ודאי פסולים בודאי פסולים, כגון ממזרים ונתינים — \u0003מותר,\u0004 אבל \u0003ודאן\u0004 \u0005[וודאים],\u0006 אלה שפסולים בודאי, כגון ממזרים \u0003בספיקן\u0004 \u0005[בספיקות],\u0006 כגון שתוקי ואסופי, או \u0003ספיקן בודאן\u0004 \u0005[ספיקות בוודאים],\u0006 \u0003ו\u0004כן \u0003ספיקן בספיקן\u0004 \u0005[ספיקות בספיקות],\u0006 כגון שתוקי באסופית — \u0003אסור. ואלו הן הספיקות: שתוקי, אסופי, וכותי\u0004 (שומרוני).","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כל האסורין לבא בקהל? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ממזירי ונתיני שתוקי ואסופי\u0004 \u0005[ממזרים, ונתינים שתוקים ואסופים]\u0006 — \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה\u0006 כבר דבר \u0005זה מתחילה],\u0006 בתחילת הפרק, ש\u0003ממזירי ונתיני שתוקי ואסופי\u0004 \u0005[ממזרים, ונתינים שתוקים ואסופים]\u0006 \u0003מותרים לבא זה בזה!\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 מה שאמרנו ש\u0003ר' יהודה אוסר, אהייא\u0004 \u0005[על איזה]\u0006 דבר אמר? \u0003אילימא אודאן בספיקן\u0004 \u0005[אם תאמר על וודאים בספיקות],\u0006 שהוא אוסר אותם — \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה\u0006 ב\u0005סוף]\u0006 \u0003ר' אליעזר אומר: ודאן בודאן\u0004 \u0005[וודאים בוודאים]\u0006 — \u0003מותר, ודאן בספיקן, וספיקן בספיקן\u0004 \u0005[וודאים בספיקות וספיקות בספיקות]\u0006 — \u0003אסור, מכלל\u0004 הדברים אתה לומד ש\u0003ר' יהודה לא סבירא ליה\u0004 \u0005[אינו סבור כן]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' יהודה אוסר\u0004 כוונתו \u0003אגר\u0004 \u0005[על גר]\u0006 שהוא אסור \u0003בממזרת,\u0004 אולם \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003גר בממזרת קתני\u0004 \u0005[שנה]\u0006 שם? הלא \u0003כל האסורין לבא בקהל קתני\u0004 \u0005[שנה]\u0006 וגר אינו בכלל האסורים לבוא בקהל!","\u0003אמר רב יהודה:\u0004"],["\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל האסורים לבא בקהל כהונה, מאי נינהו\u0004 \u0005[מה הם]\u0006 — אף \u0003גיורת פחותה מבת שלש שנים ויום אחד, ודלא\u0004 \u0005[ושלא]\u0006 \u0003כ\u0004דברי \u0003ר' שמעון בן יוחי,\u0004 שמתיר אותה לכהונה — \u0003מותרין לבוא זה בזה,\u0004 כלומר, באסורים לבוא בקהל.","ושואלים: \u0003ונוקמה\u0004 \u0005[ונעמידנה]\u0006 את ההלכה הזו גם \u0003בבת שלש שנים ויום אחד, ואפילו לר' שמעון בן יוחי!\u0004 ומשיבים: \u0003אם כן מצידה\u0004 (מצד עצמה) הלכה זו היא \u0003תברה\u0004 \u0005[שבורה,\u0006 סתורה\u0005],\u0006 שאם היינו מבינים את משמעות הדברים במובן ש\"אף גיורת בת שלוש שנים ויום אחד מותרת לבוא זה בזה\" היינו מדייקים:","\u0003אלא טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בת שלש שנים ויום אחד\u0004 היא שמותרת לבוא זה בזה עם האסורים לבוא בקהל, \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה \u0003פחותה מבת שלש שנים ויום אחד\u0004 ש\u0003מותרת לבא בקהל כהונה\u0004 — \u0003אסורה לבוא זה בזה?\u0004 ויש להקשות: \u0003הרי פחותה מבת שלש שנים ויום אחד ל\u0004דעת \u0003ר' שמעון בן יוחי\u0004 ש\u0003מותרת לבא בקהל כהונה ומותרות לבא זה בזה\u0004 גם בפסולים! ואם כן לא נוכל להעמיד את המשנה גם באופן זה.","ושואלים עוד: \u0003וכללא\u0004 \u0005[ו\u0006האם \u0005כלל]\u0006 \u0003הוא\u0004 ש\u0003כל האסורים לבא בקהל כהונה מותרין לבא זה בזה? והרי אלמנה\u0004 לכהן גדול \u0003וגרושה וחללה וזונה\u0004 ש\u0003אסורים לבא בקהל כהונה, ואסורים לבא זה בזה\u0004 בפסולי קהל! \u0003ותו\u0004 \u0005[ועוד]\u0006 האם תדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 זה \u0003מותר\u0004 לבוא בקהל כהונה \u0003אסור\u0004 לבוא בפסולים לקהל? \u0003והרי גר שמותר בכהנת ומותר בממזרת!\u0004","\u0003אלא אמר רב נתן בר הושעיא: הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא במשנה: \u0003כל שכהן אסור לישא את בתו, ומאי ניהו\u0004 \u0005[ומיהו זה]\u0006 — \u0003גר שנשא גיורת. וכ\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 האוסר בני שני גרים לכהונה — \u0003מותרין לבא זה בזה\u0004 בפסולי קהל, שאין הגרים נחשבים \"קהל\".","ושואלים: \u0003וכללא\u0004 \u0005[וכלל]\u0006 \u0003הוא\u0004 ש\u0003כל שכהן אסור לישא את בתו מותרים לבא זה בזה? הרי חלל שנשא בת ישראל,\u0004 ש\u0003כהן אסור לישא\u0004 את \u0003בתו\u0004 משום שהיא חללה, \u0003ואסורין נמי\u0004 \u0005[גם כן]\u0006 \u0003לבא זה בזה,\u0004 שהרי הבת הזאת נחשבת כישראלית, ואסור לה להינשא לפסול! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 כי הלכה היא זו \u0003כר' דוסתאי בן יהודה\u0004 האומר שבת חלל מישראלית מותרת לכהונה, ואם כן אין החלל בגדר \"כהן אסור לישא את בתו\".","ומקשים: \u0003והרי חלל שנשא חללה וכהן אסור לישא בתו\u0004 שהיא חללה, \u0003ואסור נמי\u0004 \u0005[גם כן]\u0006 \u0003לבא זה\u0004 \u0003בזה\u0004 בפסולי קהל! \u0003ותו\u0004 \u0005[ועוד]:\u0006 נדייק מהלכה זו \u0003הא\u0004 \u0005[הרי]\u0006 מי שהוא \u0003מותר\u0004 לבוא בכהונה \u0003אסור\u0004 לבוא בפסולים? \u0003והרי גר שנשא בת ישראל, וכהן מותר לישא בתו, ומותרין לבא זה בזה\u0004 בפסולי קהל!","\u0003אלא אמר רב נחמן אמר רבה בר אבוה\u0004 הסבר אחר למחלוקת תנא קמא ור' יהודה: \u0003הכא\u0004 \u0005[כאן]\u0006 לענין \u0003ממזר מ\u0004איש שבא על \u0003אחותו וממזר מאשת איש איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל:","\u0003תנא קמא סבר\u0004 \u0005[סבור]:\u0006 \u0003אפילו ממזר מאחותו נמי הוי\u0004 \u0005[גם כן הוא\u0006 נחשב\u0005]\u0006 ל\u0003ממזר. ור' יהודה סבר: מאשת איש הוי\u0004 \u0005[הריהו]\u0006 \u0003ממזר, מאחותו\u0004 — \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003ממזר.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 התנא בכך? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה בברייתא: \u0003איזהו ממזר\u0004 — \u0003כל שהוא\u0004 נולד \u0003ב\u0004איסור של \u0003\"לא יבא\"\u0004 (דברים כג, ב), כלומר, אם עבר על איסור ביאה כלשהו, אפילו בלאו, הרי הוולד מנישואין הללו ממזר, אלה \u0003דברי ר' עקיבא.\u0004","\u0003שמעון התימני אומר: כל שחייבין עליו כרת בידי שמים\u0004 על הביאה, \u0003והלכה כדבריו. ר' יהושע אומר: כל שחייבין עליו מיתת בית דין.\u0004 ואם כן השאלה אם מי שנולד מאחותו (שהוא חיוב כרת ולא מיתת בית דין) נחשב לממזר כבר נדונה, ותלויה במחלוקת תנאים, ואם כן יש לדחות מה שאמרנו.","\u0003אלא אמר רבא:\u0004 בדין \u0003גר עמוני ומואבי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003כל האסורים לבא בקהל, ומאי ניהו\u0004 \u0005[ומה הם]:\u0006 \u0003גר עמוני ומואבי\u0004 — \u0003מותרין לבא זה בזה.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ר' יהודה אוסר?\u0004 הלא ודאי גם הוא מתיר גר עמוני בממזרת, שהרי אינו ראוי לבוא בקהל! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי שר' יהודה אוסר\u0004 בדרך כלל \u0003גר בממזרת,\u0004 בכל זאת \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בסתם \u0003גר\u0004 ש\u0003ראוי לבא בקהל, אבל גר עמוני ומואבי\u0004 ש\u0003אין ראויין לבא בקהל\u0004 — \u0003לא\u0004 נאסרו לשאת ממזרת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ילד \u0003בן תשע שנים ויום אחד\u0004 שביאתו לענין איסור נחשבת ביאה שהיה \u0003גר עמוני,\u0004 או גר \u0003מואבי,\u0004 או גר \u0003מצרי ,\u0004 או גר \u0003אדומי,\u0004 או שהיה \u0003כותי,\u0004 או \u0003נתין,\u0004 או \u0003חלל,\u0004 או \u0003ממזר שבאו על הכהנת\u0004 או \u0003על הלויה\u0004 או \u0003על בת ישראל\u0004 — \u0003פסלוה\u0004 מן הכהונה על ידי ביאה זו. \u0003ר' יוסי אומר: כל שזרעו פסול\u0004 שגם הילדים שלו פסולים לכהונה — \u0003פוסל\u0004 את זו שבא עליה מהכהונה, \u0003וכל שאין זרעו פסול\u0004 — \u0003אינו פוסל. רבן שמעון בן גמליאל אומר:\u0004"],["\u0003כל שאתה נושא בתו\u0004 — \u0003אתה נושא אלמנתו,\u0004 שאדם שמותר לכהן לשאת את בתו מותר לו לשאת גם את אלמנתו, כלומר, שלא נפסלה לכהונה בביאתו. \u0003וכל שאי\u0004 (אין) \u0003אתה נושא בתו\u0004 — \u0003אי אתה נושא אלמנתו.\u0004","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 הבדל בהלכה \u0003בין\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון\u0006 במשנה\u0005]\u0006 \u0003ובין ר' יוסי,\u0004 שלכאורה יוצא מדבריהם אותו דבר? \u0003אמר ר' יוחנן:\u0004 בענין \u0003מצרי שני איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, שחולקים הם בדינה של ישראלית שנבעלה לגר מצרי בדור שני. \u0003ושניהם לא למדוה\u0004 את ההלכה שלהם \u0003אלא מ\u0004דין \u0003כהן גדול באלמנה,\u0004 אבל למדים הם באופנים שונים. כיצד?","שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003כהן גדול באלמנה; מה כהן גדול באלמנה שביאתו\u0004 עליה באה \u0003בעבירה ופוסל בה\u0004 (אותה) מלהינשא לכהונה — \u0003אף כל שביאתו בעבירה,\u0004 כגון מצרי שני שבא על ישראלית — \u0003פוסל.\u0004","\u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]\u0006 שהלימוד הוא \u0003: כי\u0004 \u0005[כמו]\u0006 \u0003כהן גדול באלמנה; מה כהן גדול באלמנה שזרעו פסול\u0004 (שהרי הוא חלל) \u0003ו\u0004כן \u0003פוסל\u0004 אותה בביאתו — \u0003אף כל שזרעו פסול\u0004 — \u0003פוסל. לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מצרי שני שאין זרעו פסול,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בנים אשר יולדו להם דור שלישי יבא להם בקהל ה'\"\u0004 (דברים כג, ט), ולכן גם אינו פוסל את האשה בביאתו.","שנינו באותה מחלוקת ש\u0003רבן שמעון בן גמליאל אומר: כל שאתה נושא בתו\u0004 — \u0003אתה נושא אלמנתו, וכל שאי אתה נושא את בתו\u0004 — \u0003אי אתה נושא אלמנתו.\u0004 ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 הבדל בהלכה \u0003בין ר' יוסי לרבן שמעון בן גמליאל,\u0004 שלכאורה אומרים הם אותו דבר? \u0003אמר עולא:\u0004 לענין \u0003גר עמוני ומואבי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שלדעת ר' יוסי גר עמוני ומואבי פוסל בביאתו את אשתו מן הכהונה, ולדעת רבן שמעון בן גמליאל אינו פוסל. \u0003ושניהם לא למדוה אלא מכהן גדול באלמנה.\u0004","ש\u0003ר' יוסי סבר: כי\u0004 \u0005[כמו]\u0006 \u0003כהן גדול באלמנה; מה כהן גדול באלמנה שזרעו פסול\u0004 — \u0003ופוסל, אף כל שזרעו פסול\u0004 אף הוא \u0003פוסל\u0004 את האשה בביאתו וכך דינו של גר עמוני ומואבי.","\u0003ורבן שמעון בן גמליאל\u0004 סבור: \u0003ככהן גדול באלמנה; מה כהן גדול באלמנה שכל זרעו פסול\u0004 בין בנים ובין בנות — פוסל את האשה בביאתו, \u0003אף כל\u0004 דבר שנלמד מאלמנה לכהן גדול זה דינם \u0003שכל זרעו פסול\u0004 ש\u0003אפילו נקבות\u0004 שבזרעו יהיו פסולות, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003גר עמוני ומואבי\u0004 ש\u0003נקבות\u0004 שנולדו להם \u0003הוו\u0004 \u0005[היו]\u0006 \u0003כשרות לבא בקהל.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עמוני\u0004 נאסר לבוא בקהל \u0003ולא עמונית, מואבי ולא מואבית.\u0004","\u0003אמר רב חסדא: הכל מודים באלמנת עיסה\u0004 (אלמנה שיש ספק אם בעלה היה חלל) \u0003שפסולה לכהונה.\u0004 ומסבירים: \u0003מאן מיקל בהני תנאי\u0004 \u0005[מיהו המקל\u0006 ביותר \u0005בין התנאים הללו]\u0006 — \u0003רבן שמעון בן גמליאל, וקאמר\u0004 \u0005[ו\u0006הוא \u0005אומר]:\u0006 \u0003כל שאתה נושא בתו\u0004 — \u0003אתה נושא אלמנתו, וכל שאי אתה נושא בתו\u0004 — \u0003אי אתה נושא אלמנתו. למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא? \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003אלמנת עיסה שפסולה לכהונה,\u0004 שכן בתו של ספק חלל ודאי אסורה לכהן.","ומעירים: ודברי רב חסדא באו \u0003לאפוקי מדהני תנאי\u0004 \u0005[להוציא\u0006 למעט \u0005מ\u0006דברי \u0005תנאים אלה]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003העיד ר' יהושע ור' יהודה בן בתירא על אלמנת עיסה שכשירה לכהונה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההיתר — \u0003הוי\u0004 \u0005[הרי הוא]\u0006 בסך הכל \u0003ספק ספיקא,\u0004 כלומר, ספק הבא מתוך ספק, שספק אם בעלה היה הפסול, ואף אם כן היה, הרי הוא רק ספק פסול, \u0003וספק ספיקא\u0004 דינו \u0003לקולא\u0004 \u0005[להקל].\u0006","שנינו במשנה שר' אלעזר אומר ש\u0003ודאן בודאן מותר\u0004 כגון ממזר בממזרת, אבל ספקן (כגון שתוקי) בודאן — אסור. \u0003אמר רב יהודה אמר רב: הלכה כ\u0004שיטת \u0003ר' אליעזר.\u0004 והוסיף רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה\u0006 ההלכה \u0005לפני]\u0006 \u0003שמואל אמר לי: הלל\u0004 הזקן היה \u0003שונה\u0004 את משנתנו: \u0003עשרה יוחסים עלו מבבל, וכולם\u0004 (כל הפסולים) \u0003מותרים לבא זה בזה, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003הלכה כר' אליעזר?!\u0004","ומעירים: \u0003ורמי דרב אדרב\u0004 \u0005[ו\u0006יש \u0005להשליך,\u0006 להראות סתירה \u0005מ\u0006דברי \u0005רב על\u0006 דברי \u0005רב],\u0006 \u0003ורמי דשמואל אדשמואל\u0004 \u0005[ולהשליך\u0006 מדברי \u0005שמואל על\u0006 דברי \u0005שמואל]\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בדבר: \u0003ארוסה שעיברה,\u0004 שהרתה בזמן האירוסין, ואין ברור ממי התעברה אם מן הארוס או מאחר, \u0003רב אמר\u0004 ש\u0003הולד ממזר,\u0004 שיש להניח שנתעברה מאדם אחר, והולד הוא ממזר מאשת איש. \u0003ושמואל אמר\u0004 ש\u0003הולד שתוקי\u0004 ואין ראיה שממזר הוא, שמא מן הארוס התעברה.","והסבר שיטותיהם, \u0003רב אמר: הולד ממזר ומותר בממזרת, ושמואל אמר: הולד שתוקי ואסור בממזרת.\u0004 נמצא ששמואל אוסר ספק (שתוקי) בודאי (ממזר), ואילו רב מתירו בממזרת! ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הדעות במחלוקת זו, ואמור ש\u0003רב אמר: הולד שתוקי\u0004 ולכן אסור בממזרת, \u0003ושמואל אמר: הולד ממזר\u0004 ומותר בממזרת.","ושואלים: אם כן \u0003תרתי\u0004 \u0005[שתי]\u0006 \u0003למה לי?\u0004 למה השמיעו שתי פעמים אותה מחלוקת שבין רב ושמואל? ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר; \u0003דאי איתמר בהא\u0004 \u0005[שאם\u0006 היה \u0005נאמר\u0006 רק \u0005בזו]\u0006 שבמשנה שמדובר שם בפנויה שוולדה שתוקי, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב משום\u0004 ש\u0003רוב כשרים אצלה,\u0004 שרק מיעוט הוא של איסורי עריות ופסולים. \u0003אבל התם\u0004 \u0005[שם]\u0006 בענין ארוסה שעיברה ש\u0003רוב פסולים אצלה,\u0004 שהרי היא אסורה לכל העולם באיסור אשת איש, \u0003אימא מודי\u0004 \u0005[אמור שמודה]\u0006 \u0003לשמואל\u0004 שהולד ממזר גמור.","ולהיפך, \u0003ואי איתמר בהך\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו],\u0006 בארוסה, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003רב\u0004 שהוא שתוקי — \u0003משום דאיכא למיתלה\u0004 \u0005[שיש\u0006 מקום \u0005לתלות אותה]\u0006 על כל פנים \u0003בארוס\u0004 שבא עליה ואין הולד ממזר ודאי, \u0003אבל בהא אימא מודי\u0004 \u0005[בזו,\u0006 בפנויה, \u0005אמור\u0006 ש\u0005מודה]\u0006 \u0003לשמואל\u0004 שהולד ודאי ממזר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את השיטות, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003ממזר דקאמר\u0004 \u0005[שאומר]\u0006 \u0003רב, לאו\u0004 \u0005[לא]\u0006 שיהא \u0003מותר בממזרת, אלא\u0004 רק ש\u0003אסור בבת ישראל. ושמואל\u0004 ש\u0003אמר\u0004 ש\u0003הולד שתוקי,\u0004 מה כוונתו — ש\u0003אסור בבת ישראל.\u0004 ומקשים: \u0003אי הכי היינו\u0004 \u0005[אם כן, זוהי]\u0006 שיטתו של \u0003רב! אלא\u0004 כך יש לפרש: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שתוקי\u0004 בדברי שמואל — \u0003שמשתקין אותו מדין כהונה,\u0004 שגם אם היה הארוס כהן, מכל מקום אין הולד הזה נחשב לכהן.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר ואין צורך לאומרו \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003מדין ישראל משתקינן ליה\u0004 \u0005[משתקים אנו אותו]\u0006 ואין מניחים לו לבוא בקהל, \u0003מדין כהונה מיבעי\u0004 \u0005[נצרכה]\u0006 לומר?! \u0003אלא\u0004 יש לומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שתוקי\u0004 — \u0003שמשתקין אותו מנכסי אביו\u0004 שאינו יורשו. ותוהים: אף זה \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 \u0003מי ידעינן אבוה מנו\u0004 \u0005[האם יודעים אנו אביו מיהו]?\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא ש\u0003תפס\u0004 בן זה מרכושו של הארוס, וטוען שהוא בנו של ארוס זה, ועל כך אמר שמואל שבכל זאת מוציאים את הנכסים מידו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שתוקי\u0004 שאמר שמואל — \u0003בדוקי,\u0004 כלומר, \u0003שבודקים את אמו, ו\u0004אם היא \u0003אומרת \"לכשר נבעלתי\"\u0004 — \u0003נאמנת.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי היא]\u0006 איפוא הל כה זו — \u0003כרבן גמליאל?\u0004 ואולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 זאת כבר \u0003שמואל חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אשה פנויה ש\u0003היתה מעוברת, ואמרו לה: מה טיבו של עובר זה?\u0004 אמרה להם: \u0003מאיש פלוני\u0004 שנבעלתי לו, \u0003וכהן הוא,\u0004 כלומר, כשר — \u0003רבן גמליאל ור' אליעזר אומרים: נאמנת. ר' יהושע אומר: אינה נאמנת. ואמר רב יהודה אמר שמואל: הלכה כרבן גמליאל.\u0004 משמע שפסק שמואל כבר במפורש כדבריו ומדוע חזר ואמר דבר זה שנית?","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר, \u0003דאי מהתם הוה אמינא\u0004 \u0005[שאם משם\u0006 במשנה ביחס למעוברת בלבד, \u0005הייתי אומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003רוב כשירים אצלה\u0004 שהרי פנויה היא, ורוב האנשים שיכולים לבוא עליה הם כשרים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בארוסה שעיברה ש\u0003רוב פסולים אצלה,\u0004 שהרי נאסרה לכל העולם באיסור אשת איש, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 תהיה נאמנת לומר שנבעלה לכשר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003וכן ר' אלעזר אומר: כותי\u0004 (שומרוני) \u0003לא ישא כותית.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב יוסף: עשאוהו,\u0004 דנו אותו חכמים, \u0003כגר לאחר עשרה דורות. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: גר עד עשרה דורות\u0004 של גרים — \u0003מותר בממזרת, מכאן ואילך\u0004 — \u0003אסור בממזרת,\u0004 משום שאין זוכרים כבר שאין מוצאו מישראל, וכן הכותים נטמעו בישראל ואין מכירים אותם.","\u0003ויש אומרים\u0004 שהוא מותר בממזרת \u0003עד שישתקע שם עבודה זרה ממנו,\u0004 שכל זמן שזוכרים שהוא מצאצאי גויים מותר עדיין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר לגר? \u0003התם\u0004 \u0005[שם]\u0006 הוא \u0003גר ישן,\u0004 כלומר, הגרות ישנה היא \u0003וממזרת חדשה,\u0004 כלומר, ידועה לנו, ועל כן \u0003אמרי\u0004 \u0005[אומרים]\u0006 אנשים כשיראו שהוא נושא ממזרת: \u0003בר\u0004 \u0005[בן]\u0006 \u0003ישראל הוא דקא נסיב\u0004 \u0005[שנשא]\u0006 \u0003ממזרת.\u0004 אבל \u0003הכא אידי ואידי כי הדדי נינהו\u0004 \u0005[כאן זה וזה,\u0006 הכותים, \u0005שווים הם]\u0006 ואין לחשוש, שאם הוא נידון כישראל, גם היא כן. \u0003אלא\u0004 יש לדחות הסבר זה ולהסביר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: ר' אלעזר סבר\u0004 \u0005[סבור]\u0006 \u0003לה\u0004 בענין זה \u0003כר' ישמעאל\u0004"],["\u0003ור' ישמעאל סבר לה\u0004 \u0005[סבור]\u0006 בהלכה אחרת \u0003כר' עקיבא.\u0004 ומסבירים את הדברים: \u0003ר' אלעזר סבר לה כר' ישמעאל\u0004 בענין אחד, ש\u0003אמר: כותים גירי אריות הם\u0004 מחמת פחד, ומעולם לא נתגיירו באמת ולענין הלכה נשארו גוים גמורים. \u0003ור' ישמעאל סבר לה כר' עקיבא,\u0004 ש\u0003אמר: גוי ועבד הבא על בת ישראל\u0004 — \u0003הולד ממזר.\u0004 וכיון שבמשך הדורות נתערבו ישראלים בין הכותים הרי הם כולם ספק ממזרים.","ושואלים: \u0003ומי סבר לה\u0004 \u0005[והאם סבור]\u0006 \u0003ר' ישמעאל כר' עקיבא\u0004 בענין זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: מנין לגוי,\u0004 או \u0003עבד שבאו על הכהנת,\u0004 או \u0003על הלויה,\u0004 או \u0003על בת ישראל\u0004 — \u0003שפסלוה\u0004 מן הכהונה — \u0003שנאמר: \"ובת כהן כי תהיה אלמנה וגרושה וזרע אין לה\u0004 ושבה אל בית אביה כנעוריה מלחם אביה תאכל\u0003\"\u0004 (ויקרא כב, יג),","ללמד: דווקא אם היתה נשואה ל\u0003מי שיש לו\u0004 דין \u0003אלמנות וגרושין,\u0004 כלומר, אדם מישראל, הריהי חוזרת לבית אביה ואוכלת בתרומה, \u0003יצא גוי ועבד שאין לו\u0004 דין \u0003אלמנות וגרושין\u0004 שאז נפסלת בביאה זו ואינה חוזרת לאכילת תרומה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שר' ישמעאל \u0003סבר לה כר' עקיבא\u0004 שהולד ממזר מגוי ועבד, אם כן לשם מה צריך לראיה זו? \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי אם \u0003ממזר הוי\u0004 \u0005[הוא]\u0006 הולד שנולד מביאת גוי, \u0003מיפסל בביאתו מיבעיא\u0004 \u0005[שפוסל\u0006 הגוי והעבד \u0005בביאתו נצרכה לומר]?!\u0006","\u0003אלא,\u0004 יש לומר ש\u0003ר' אלעזר סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' ישמעאל,\u0004 ש\u0003אמר כותים גירי אריות. ו\u0004ר' אלעזר עצמו \u0003סבר לה כר' עקיבא\u0004 ש\u0003אמר: גוי ועבד הבא על בת ישראל הולד ממזר.\u0004","ומקשים: \u0003ומי סבר לה\u0004 \u0005[והאם סבור]\u0006 \u0003ר' אלעזר כר' עקיבא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: אף על פי שנחלקו בית שמאי ובית הילל ב\u0004דין \u0003צרות,\u0004 אם צרתה של יבמה שאסורה ליבם משום ערוה חייבת או פטורה מייבום, מכל מקום \u0003מודים\u0004 הם \u0003שאין ממזר אלא ממי שאיסורו איסור ערוה וענוש כרת!\u0004 ואם כן לדעת ר' אלעזר גוי ועבד, כיון שאין בביאתם עונש כרת — ממילא אין הולד מהם ממזר!","\u0003אלא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' חייא בר אבא, אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבא בר זבדא, אמר ר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יעקב בר אידי, אמר ר' יהושע בן לוי: שלש מחלוקות,\u0004 שיטות, \u0003בדבר;\u0004","\u0003ר' ישמעאל סבר: כותים גירי אריות הן, וכהנים שנטמעו בהם\u0004 בזמן עזרא — \u0003כהנים פסולים היו, שנאמר: \"ויעשו להם מקצותם כהני במות\"\u0004 (מלכים ב, יז, לב), \u0003ואמר רבה בר בר חנה אמר ר' יוחנן:\u0004 מה פירוש \"מקצותם\" — \u0003מן הקוצים שבעם,\u0004 כלומר, מן הפגומים והפסולים. \u0003ומשום הכי פסלינהו\u0004 \u0005[כך פסל אותם],\u0006 לא משום הכותים עצמם שהם גויים, ואם נתגייר אחד מהם — הריהו גר גמור, אלא משום שמעורבים בהם פסולי ישראל. ושמא כותי זה הבא לשאת אשה הוא ממשפחה ישראלית פסולה.","\u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003כותים גירי אמת הן, וכהנים שנטמעו בהן\u0004 — \u0003כהנים כשרים היו, שנאמר: \"ויעשו להם מקצותם כהני במות\", ואמר רבה בר בר חנה אמר ר' יוחנן:\u0004 שהוא מפרש \"מקצותם\" — \u0003מן הבחירים\u0004 (הקצה העליון) \u0003שבעם. ואלא מפני מה אסרום\u0004 לבוא בקהל אם אין בהם חשש מצד גירות ולא מצד ישראל שמעורבים בהם — \u0003מפני\u0004 שהיו נוהגים שלא כהלכה, \u0003שהיו מייבמים את הארוסות\u0004 שאת מצוות הייבום היו מקיימים רק באלמנה מן האירוסין"],["\u0003ופוטרים את הנשואות\u0004 מן החליצה. ומסבירים: \u0003מאי דרשי\u0004 \u0005[מה\u0006 היו \u0005דורשים]\u0006 במקרא שהגיעו למסקנה זו — ממה שנאמר \u0003\"לא תהיה אשת המת החוצה לאיש זר\u0004 יבמה יבוא עליה ולקחה לו לאשה ויבמה\u0003\"\u0004 (דברים כה, ה), ופירשו \"החוצה\" כתואר לאשה: \u0003הך דיתבה חוצה\u0004 \u0005[זו שיושבת בחוץ],\u0006 כלומר, שעדיין היא ארוסה — \u0003היא לא תהיה לאיש זר,\u0004 ועליה יש חובת יבום. \u0003אבל הך דלא יתבה חוצה\u0004 \u0005[זו שאינה יושבת בחוץ],\u0006 שכבר נישאה — \u0003תהיה לאיש זר.\u0004 ואם כן החשש בכותים הוא מפני שיש ביניהם ילדים בני יבמה שנישאה לזר שלא כדין.","\u0003ור' עקיבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: יש ממזר מחייבי לאוין,\u0004 ולפיכך בני יבמה זו שעברה על \"לא תהיה אשת המת\" — הם ממזרים.","\u0003ויש אומרים\u0004 שיטה שלישית, למה פסלום: \u0003לפי שאין בקיאין בדקדוקי מצות.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003יש אומרים\u0004 אלה? \u0003אמר רב אידי בר אבין:\u0004 דעת \u0003ר' אליעזר היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצת כותי מותרת\u0004 באכילה בפסח, \u0003ואדם יוצא בה ידי חובתו בפסח, ור' אליעזר אוסר, לפי שאין\u0004 הכותים \u0003בקיאים בדקדוקי מצות\u0004 ויש חשש שמצה זאת היא חמץ. \u0003רבן שמעון בן גמליאל אומר:\u0004 שאין לחשוש לכך, כי \u0003כל מצוה שהחזיקו בה כותים\u0004 ומקיימים אותה — \u0003הרבה מדקדקים בה, יותר מישראל.\u0004","ושואלים: \u0003ואלא הכי\u0004 \u0005[כך]\u0006 בענין נישואין, \u0003מאי\u0004 \u0005[מה]\u0006 ענין \u0003אין בקיאין?\u0004 ומשיבים: \u0003לפי שאין בקיאין בתורת קידושין וגירושין\u0004 ואינם יודעים את דיניהם, יש איפוא לחשוש שגירושיהם אינם כשרים או שנתקדשה האשה והם פוטרים אותה בלא גט שאז הוולד ממזר.","\u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 כותים פסולים משום ש\u0003ממזר מאחותו וממזר מאשת אח נתערבו בהן\u0004 ולפיכך כולם ספק ממזרים. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בזה שאמר בדיוק איזה ממזרים היו? אם כדי ללמדנו אגב כך את ההלכה ש\u0003יש ממזר מחייבי כריתות\u0004 — \u0003ניתני חדא\u0004 \u0005[\u0006ש\u0005ישנה\u0006 רק \u0005אחת],\u0006 כגון ממזר מאחותו! ומשיבים: לא לצורך הלכה אמר אלא \u0003מעשה שהיה כך היה\u0004 שכך אירע בהם, ומפני כן פסלום.","\u0003ו\u0004אילו \u0003רבא אמר: עבד ושפחה נתערבו בהן.\u0004 ושואלים: \u0003איסורא\u0004 \u0005[האיסור]\u0006 שיש בהם \u0003משום מאי\u0004 \u0005[מה]\u0006 הוא? הלא הוא רק \u0003משום שפחה\u0004 שולדותיה הם עבדים, ואם כן \u0003ניתני חדא\u0004 \u0005[שישנה\u0006 רק \u0005אחת]\u0006 ולמה לשנות עבד, שהרי ולד העבד מישראלית אינו פסול! ומשיבים: \u0003מעשה שהיה כך היה,\u0004 שהיו גם עבד וגם שפחה.","כהן \u0003הנושא אשה כהנת\u0004 — \u0003צריך לבדוק אחריה ארבע אמהות,\u0004 כלומר, בדורות שקדמו לה הן מצד אמה הן מצד אביה, \u0003שהן שמנה.\u0004 שבודק הן מצד אביה והן מצד אמה בדורות שמעליהן. כיצד: בודק ביוחסין של \u0003אמה, ואם אמה, ואם אבי אמה, ואמה\u0004 של אם אבי אמה, \u0003ואם אביה\u0004 של הכלה \u0003ואמה\u0004 של אם אביה, \u0003ואם אבי אביה ואמה\u0004 של זו. ואם נשא \u0003לויה וישראלית מוסיפין עליהן עוד\u0004 בדיקה של אם \u0003אחת,\u0004 דור נוסף למעלה.","ולענין בדיקה זו, \u0003אין בודקין לא מן המזבח ולמעלה,\u0004 כלומר, אם היה בין אבותיה אדם כהן שעבד עבודה על גבי המזבח, אין צריכים לבדוק עוד את ייחוסו שכבר בדקוהו בית דין בשעתו כדי להכשירו לשמש בכהונה, \u0003ולא מן הדוכן ולמעלה,\u0004 במי שהיה לוי, והוכח ששר עם הלויים בדוכן, \u0003ולא מן הסנהדרין ולמעלה,\u0004 שאין מושיבים בסנהדרין אלא מי שאין בו פגם יוחסין. \u0003ו\u0004כן \u0003כל\u0004 מי \u0003שהוחזקו אבותיו משוטרי הרבים\u0004 (שהיה בעל תפקיד של שררה על הציבור) או מ\u0003גבאי צדקה\u0004 — \u0003משיאין\u0004 אותם \u0003לכהונה ואין צריך לבדוק אחריהן,\u0004 שחזקה שאין ממנים פסול לתפקידים אלה.","\u0003ר' יוסי אומר: אף מי שהיה חתום\u0004 כ\u0003עד בערכי\u0004 (בית הדין) \u0003הישנה של ציפורי. ר' חנינא בן אנטיגנוס אומר: אף מי שהיה מוכתב\u0004 כתוב ורשום ברשימות \u0003באסטרטיא\u0004 (צבא) \u0003של מלך\u0004 ישראל.","שואלים: \u0003מאי שנא בנשי בדקינן ומאי שנא בגברי לא בדקו\u0004 \u0005[מה שונה\u0006 ש\u0005בנשים אנו בודקים ומה שונה\u0006 ש\u0005בגברים אין בודקין]?\u0006 ומדוע לא יבדקו גם את האבות של הכלה אם אין בהם פסול? ומשיבים: \u0003נשי דכי מינצו בהדי הדדי\u0004 \u0005[נשים כאשר\u0006 הן \u0005רבות זו עם זו]\u0006 — \u0003ב\u0004האשמה של \u0003עריות הוא דמינצו\u0004 \u0005[ש\u0006הן \u0005רבות],\u0006 כלומר, בשעת מריבה מאשימה אחת את חברתה בזנות, \u0003ואם איתא דאיכא מילתא\u0004 \u0005[ואם יש\u0006 מציאות \u0005שהיה\u0006 באשה \u0005דבר]\u0006 של פסול משפחה — \u0003לא אית ליה קלא\u0004 \u0005[אין לו קול],\u0006 משום שנשים אינן מגנות זו את זו בענין היוחסין, ולעומת זאת \u0003גברי דכי מינצו בהדי הדדי\u0004 \u0005[גברים שכאשר\u0006 הם \u0005רבים זה עם זה]\u0006 — \u0003ביוחסין הוא דמינצי\u0004 \u0005[שרבים],\u0006 שאחד מגנה את חבירו שיש בו פסול יוחסין — \u0003אם איתא דאיכא מילתא\u0004 \u0005[אם יש\u0006 מקום \u0005ש\u0006באמת \u0005היה דבר]\u0006 של פגם יוחסין, \u0003אית ליה קלא\u0004 \u0005[יש לו קול]\u0006 והיה הדבר נודע לרבים גם לפני בדיקה.","ושואלים מצד אחר: כשם שאמרנו שהאיש בודק אחר ארבע אמהות אחר אשתו, \u0003ואיהי נמי תבדוק ביה בדידיה\u0004 \u0005[והיא גם כן\u0006 ש\u0005תבדוק בו]\u0006 בבעלה ביחס לייחוסו? ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב,\u0004 ש\u0003אמר רב יהודה אמר רב: לא הוזהרו\u0004 כהנות \u0003כשרות לינשא לפסולים,\u0004 כגון חללים או גרים ועבדים משוחררים, ולכן אין חובה על הנשים לעשות בדיקה כזו.","\u0003רב אדא בר אהבה תני\u0004 \u0005[שנה]:\u0006 \u0003ארבע אמהות שהם שתים עשרה,\u0004 כלומר, בכל אחד מהורי האשה שאמרו בודק עוד שתי אמהות למעלה. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003ארבע אמהות שהם שש עשרה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב אדא בר אהבה\u0004"],["\u0003מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 את ההלכה שלו \u0003בלויה ובת ישראל,\u0004 שנאמר במשנה שבודק עוד דור אחד ואפשר להתאים את דבריו לדברי המשנה. \u0003אלא מתניתא נימא פליגא\u0004 \u0005[הברייתא\u0006 האם \u0005נאמר\u0006 שהיא \u0005חולקת]\u0006 על המשנה? ודוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עוד אחת\"\u0004 שבמשנה — כוונתו \u0003זוג אחת,\u0004 כלומר, עוד שתי אמהות מכל צד.","\u0003אמר רב יהודה אמר רב:\u0004 משנתנו \u0003זו\u0004 היא \u0003דברי ר' מאיר\u0004 היא, \u0003אבל חכמים אומרים: כל משפחות בחזקת כשרות הן עומדות\u0004 ואין צורך לבדוק. ומקשים: \u0003איני\u0004 \u0005[האם כך]\u0006 אמר רב? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חמא בר גוריא אמר רב: משנתינו\u0004 מדברת דווקא במשפחה \u0003כשקורא עליו ערער,\u0004 כשיש מישהו שמערער על יחוס המשפחה, אבל כשאין ערעור, לדעת כולם בחזקת כשרות הן עומדות! ומשיבים: \u0003מאן דמתני הא\u0004 \u0005[מי ששונה זו]\u0006 בשם רב — \u0003לא מתני הא\u0004 \u0005[אינו שונה זו].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב יהודה אמר רב: זו דברי ר' מאיר, אבל חכמים אומרים: כל משפחות בחזקת כשרות הן עומדות. אמר רב חמא בר גוריא אמר רב: אם קורא עליו ערער,\u0004 במקרה זה \u0003צריך לבדוק אחריה\u0004 לפי כולם, ואם כן אין כאן סתירה אלא השלמת דברים.","שנינו במשנה ש\u0003אין בודקין מן המזבח ולמעלה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של דבר — \u0003אי לאו דבדקוה\u0004 \u0005[אם לא שהיו בודקים אותו]\u0006 בבית דין הגדול בייחוסו \u0003לא הוו מסקי ליה\u0004 \u0005[היו מעלים אותו]\u0006 לעבוד. ועל מה ששנינו במשנה \u0003ולא מן הדוכן ולמעלה,\u0004 שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים: ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בתוך תיאור הלשכות שבמקדש: \u0003ששם\u0004 בלשכת הגזית \u0003היו יושבים מייחסי כהונה ומייחסי לויה\u0004 והיו בודקים יחוסם של כל העובדים במקדש.","ועל מה ששנינו במשנה \u0003ולא מסנהדרין ולמעלה,\u0004 שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין בודקים? ומשיבים: \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003כשם שבית דין מנוקין בצדק\u0004 — \u0003כך מנוקין מכל מום\u0004 שאין בהם פגם יוחסין. \u0003אמר מרימר: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — שנאמר \u0003\"כלך יפה רעיתי ומום אין בך\"\u0004 (שיר השירים ד, ז).","ושואלים: \u0003אימא מומא\u0004 \u0005[אמור\u0006 שהכוונה ל\u0005מום]\u0006 \u0003ממש,\u0004 כלומר, שהכוונה היא שהיושבים בסנהדרין אסור שיהיו בעלי מומים בגופם! \u0003אמר רב אחא בר יעקב:\u0004 דבר זה אינו צריך לימוד מכתוב זה, כי כבר \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בהאצלת הרוח על זקני העם בימי משה רבינו: \u0003\"והתיצבו שם עמך\"\u0004 (במדבר יא, טז), שיש לפרש \u0003\"עמך\"\u0004 — \u0003בדומים לך,\u0004 שגם הם צריכים להיות בשלימות הגוף כמשה רבינו, ומכאן למדים שחכמי הסנהדרין אסור שיהא בהם מום גופני.","את הראיה הזו דוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הם שונים \u0003משום\u0004 שהיה צריך שתהיה עליהם השראת \u0003שכינה\u0004 היו צריכים להיות מנוקים ממום, אבל אין ללמוד מכאן לגבי דיינים סתם! \u0003אמר רב נחמן, אמר קרא\u0004 \u0005[הכתוב]\u0006 במקום אחר: \u0003\"והקל מעליך ונשאו אתך\"\u0004 (שמות יח, כב), כוונתו \u0003בדומים לך,\u0004 שמנוקים ממומי הגוף. ובפסוק זה מדובר במינוי דיינים ללא השראת שכינה.","שנינו במשנה ש\u0003כל מי שהוחזקו אבותיו משוטרי הרבים\u0004 משיאין אותו לכהונה. ושואלים: \u0003למימרא דלא מוקמינן\u0004 \u0005[\u0006האם \u0005לומר\u0006 מכאן \u0005שאין אנו מעמידים]\u0006 שוטרים וממונים \u0003מפסולים? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003הכל כשרים לדון דיני ממונות, ואין הכל כשרים לדון דיני נפשות. והוינן\u0004 \u0003בה\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה,\u0004 בהלכה זו: \u0003\"הכל\" לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה]?\u0006 \u0003ואמר רב יהודה: לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003ממזר,\u0004 שכשר לדון בדיני ממונות. משמע שאפילו ממזר יכול להיות משוטרי הרבים! \u0003אמר אביי:\u0004 במשנה מדובר בשוטרי הרבים \u0003בירושלים,\u0004 שהיו מדקדקים שיהיו כל דייניהם מיוחסים. \u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003רב שמעון בר זירא בקידושי דבי\u0004 \u0005[ב\u0006ברייתא של \u0005קידושין\u0006 שנשנתה \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003לוי:\u0004 בשוטרי הרבים \u0003בירושלים.\u0004","שנינו במשנה שאת \u0003גבאי\u0004 ה\u0003צדקה משיאים\u0004 לכהונה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים: \u0003כיון דמנצו\u0004 \u0005[ש\u0006הם \u0005רבים]\u0006 \u0003בהדי אינשי\u0004 \u0005[עם בני אדם]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 הגבאים הממונים על כך \u0003ממשכנים על הצדקה,\u0004 שרשאים לקחת משכון מאדם שנתחייב לתת צדקה ואינו נותן, \u0003ואפילו\u0004 היה הדבר \u0003בערב שבת\u0004 שאז אנשים טרודים וממהרים, \u0003ואם איתא דאיכא\u0004 \u0005[ואם יש\u0006 מקום לומר \u0005שיש]\u0006 במשפחת הגבאי איזה פסול משפחה — \u0003אית ליה קלא\u0004 \u0005[יש לו קול],\u0006 שאם היה בו פגם משפחה היה הדבר מתגלה לרבים בשעת מריבה.","מסופר: \u0003אושפזיכניה\u0004 \u0005[מארחו]\u0006 של \u0003רב אדא בר אהבה גיורא הוה\u0004 \u0005[גר היה]\u0006 \u0003והוה קא מנצי איהו\u0004 \u0005[והיו רבים הוא]\u0006 \u0003ורב ביבי, מר\u0004 \u0005[אדם זה]\u0006 \u0003אמר: אנא עבידנא סררותא דמתא\u0004 \u0005[אני עושה\u0006 את \u0005השררה של העיר],\u0006 אני אהיה פרנס העיר, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003אמר: אנא עבידנא סררותא דמתא\u0004 \u0005[אני עושה\u0006 את \u0005שררת העיר].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר\u0004 \u0003ב יוסף\u0004 שיכריע ביניהם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003\"שום תשים עליך מלך... מקרב אחיך\"\u0004 (דברים יז, טו), לומר: \u0003כל משימות\u0004 (מינויים) \u0003שאתה משים\u0004 — ולא של מלכות בלבד \u0003לא יהיה אלא מקרב אחיך,\u0004 ולכן אין ממנים גר לשררה על ישראל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה: ו\u0004דין זה הוא \u0003אפילו\u0004 אם \u0003אמו\u0004 של אותו גר \u0003מישראל? אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: אם \u0003אמו מישראל\u0004 — \u0003\"מקרב אחיך\" קרינא ביה\u0004 \u0005[קוראים אנו בו].\u0006 \u0003הלכך\u0004 \u0005[משום כך]\u0006 שהתברר שאותו גר היתה אמו מישראל וראוי להתמנות על הציבור, \u0003רב ביבי דגברא רבא\u0004 \u0005[שאדם גדול\u0006 בתורה\u0005]\u0006 \u0003הוא ליעיין במילי דשמיא\u0004 \u0005[יתעסק בעניני שמים],\u0006 בענייני העיר הנוגעים למצוות, \u0003ומר\u0004 \u0005[ואדוני],\u0006 אותו גר שהיה מארחו של רב אדא בר אהבה \u0003ליעיין במילי דמתא\u0004 \u0005[יעסוק בענייני העיר]\u0006 האחרים. \u0003אמר אביי\u0004 כלקח מסיפור זה: \u0003הלכך מאן דמשרי צורבא מדרבנן באושפיזיכניה\u0004 \u0005[לכן, מי שמחזיק תלמיד חכם כאורח],\u0006 \u0003לאשרי\u0004 \u0005[שיאכסן\u0006 אצלו אדם\u0005]\u0006 \u0003כרב אדא בר אהבה דידע למהפיך ליה בזכותיה\u0004 \u0005[שיודע להפוך בזכותו],\u0006 שהרי בגללו קיבל המארח את שררת העיר.","מסופר: \u0003ר' זירא מטפל בהו\u0004 \u0005[היה מטפל בהם]\u0006 בגרים, ונותן להם תפקידים, וכן \u0003רבה בר אבוה מטפל בהו\u0004 \u0005[בהם].\u0006 \u0003במערבא\u0004 \u0005[בארץ ישראל]\u0006 \u0003אפילו ריש כורי\u0004 \u0005[ממונה על המידות]\u0006 \u0003לא מוקמי מינייהו\u0004 \u0005[היו מעמידים מהם,\u0006 מגרים\u0005].\u0006 \u0003בנהרדעא אפילו ריש גרגותא\u0004 \u0005[ממונה על השקיית שדות העיר]\u0006 \u0003לא מוקמי מינייהו\u0004 \u0005[היו מעמידים מהם].\u0006","שנינו במשנה ש\u0003ר' יוסי אומר: אף מי שהיה\u0004 חתום בערכי הישנה של ציפורי אין צורך בבדיקת יחוסו למעלה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שם היו \u0003דייקי ומחתמי\u0004 \u0005[מדקדקים\u0006 בעדים ואחר כך \u0005מחתימים\u0006 אותם\u0005]\u0006 ולכן מי שחתם שם כעד ודאי כשר היה.","שנינו במשנה ש\u0003ר' חנינא בן אנטיגנוס\u0004 אומר: אף מי שהיה מוכתב באסטרטיא של מלך אין צריך לבדוק ביחוסו. \u0003אמר רב יהודה אמר שמואל:\u0004 מדובר שם \u0003בחיילות\u0004 (גדודי צבא) \u0003של בית דוד\u0004 שהיו מיוחסים. \u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מה הכתוב]\u0006 המלמדנו דבר זה — שנאמר: \u0003\"והתיחשם בצבא במלחמה\"\u0004 (דברי הימים א ז, מ). ושואלים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005למה]\u0006 היו צריכים בעלי יוחסין? \u0003אמר רב יהודה אמר רב: כדי שתהא זכותן וזכות אבותם מסייעתן\u0004 במלחמה.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בין גיבורי דוד \u0003צלק העמוני\u0004 (שמואל ב כג, לז), \u0003מאי לאו דאתי\u0004 \u0005[האם לא\u0006 הכוונה \u0005ש\u0006הוא \u0005בא]\u0006 \u0003מעמון\u0004 והיה גר? ודוחים: \u0003לא,\u0004 הכוונה היא \u0003דיתיב\u0004 \u0005[שישב,\u0006 התגורר\u0005]\u0006 \u0003בעמון\u0004 אבל הוא עצמו היה יהודי. \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003אוריה החתי\u0004 (שם, לט), \u0003מאי לאו דאתי\u0004 \u0005[האם לא ש\u0006הוא \u0005בא]\u0006 \u0003מחת?\u0004 ודוחים: \u0003לא, דיתיב\u0004 \u0005[שהיה יושב,\u0006 מתגורר\u0005]\u0006 \u0003בחת.\u0004","ועוד שואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003אתי הגיתי\u0004 (שם טו, יט)! \u0003וכי תימא הכי נמי דיתיב\u0004 \u0005[ואם תאמר כך גם כן\u0006 הפירוש \u0005שהיה יושב,\u0006 מתגורר\u0005]\u0006 \u0003בגת,\u0004 אבל היה יהודי — \u0003והא\u0004 \u0005[והרי]\u0006 בפתרון השאלה כיצד יכול היה דוד להשתמש בעטרת מלכם, אלילם של בני עמון, והרי אסור ליהנות מעבודה זרה, \u0003אמר רב נחמן: אתי הגיתי בא ובטלה\u0004 מדין עבודה זרה. שהלכה היא שדווקא אם גוי מבטל עבודה זרה, כגון על ידי מעשה בזיון — בטל האיסור ממנה, ומכאן מוכח שהיה איתי הגיתי גוי!","\u0003ועוד\u0004 יש להקשות ש\u0003אמר רב יהודה אמר רב: ארבע מאות ילדים\u0004 (אנשים צעירים) \u0003היו לו לדוד\u0004 במחנהו, \u0003וכולם בני יפת תואר היו,\u0004 שנולדו מאשת יפת תואר והיו גויים, \u0003וכולם\u0004 היו \u0003מסתפרים קומי, ומגדלים בלורית היו\u0004 כגויים, \u0003וכולם יושבים בקרוניות של זהב והיו מהלכים בראשי גייסות\u0004 בצבאו של דוד, \u0003והן הן בעלי אגרופים של בית דוד\u0004 שהיה בית דוד נשען על כוחם של אלה. משמע שבצבא דוד היו גם חיילים שלא היו מיוחסים! ומשיבים: ארבע מאות אלה לא היו ממש עם צבאו של דוד, אלא \u0003דאזלי לבעותי עלמא\u0004 \u0005[שהיו הולכים\u0006 בראש \u0005להפחיד את הכל]\u0006 ולא היו מנויים ברשימת אנשי הצבא של המלך."],["\u0003בת חלל זכר\u0004 — \u0003פסולה מן הכהונה לעולם.\u0004 כלומר, כל אשה מבניו או מבני בניו של החלל, אף לאחר כמה דורות, אסורה לכהונה משום פסול חללות. \u0003ישראל שנשא חללה\u0004 — \u0003בתו כשירה לכהונה.\u0004 ואילו \u0003חלל שנשא בת ישראל\u0004 — \u0003בתו פסולה לכהונה. ר' יהודה אומר: בת גר זכר\u0004 הריהי \u0003כבת חלל זכר\u0004 ואף היא אסורה לכהונה.","\u0003ר' אליעזר בן יעקב\u0004 חולק עליו ו\u0003אומר: ישראל שנשא גיורת\u0004 — \u0003בתו כשירה לכהונה, וגר שנשא בת ישראל\u0004 — \u0003בתו כשירה לכהונה, אבל גר שנשא גיורת\u0004 — \u0003בתו פסולה לכהונה. אחד גר ואחד עבדים\u0004 \u0003משוחררים אפילו עד עשרה דורות\u0004 בנותיהן פסולות לכהונה, \u0003עד שתהא אמו מישראל. ר' יוסי אומר: אף גר שנשא גיורת בתו כשירה לכהונה.\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 ענין \u0003לעולם\u0004 שאמרנו, שבתו של חלל פסולה לעולם? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 ביחס ל\u0003מצרי ואדומי, מה להלן\u0004 במצרי ואדומי \u0003לאחר שלשה דורות\u0004 מותרים צאצאיהם לבוא בקהל, \u0003אף כאן נמי\u0004 \u0005[גם כן],\u0006 \u0003לאחר שלשה דורות\u0004 תהא בת מזרעו של חלל מותרת לכהונה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאיסור זה הוא לעולם.","שנינו במשנה ש\u0003ישראל שנשא חללה\u0004 — בתו כשירה לכהונה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון: נאמר כאן \"ולא יחלל זרעו בעמיו\"\u0004 (ויקרא כא, טו) \u0003ונאמר להלן \"לא יטמא בעל בעמיו\u0004 להחלו\u0003\"\u0004 (שם, ד), \u0003מה להלן\u0004 איסור הכהנים ליטמא למת הוא רק לגבי \u0003זכרים ולא נקבות, אף כאן\u0004 בענין חילול זרעו \u0003זכרים\u0004 נפסלים ופוסלים את בתם לכהונה כשהם חללים \u0003ולא נקבות.\u0004","ושואלים: \u0003אלא מעתה\u0004 שהחילול נוגע לזכרים בלבד, \u0003בתו של כהן גדול\u0004 מאלמנה \u0003תישתרי\u0004 \u0005[תהיה מותרת]\u0006 לכהונה! ודוחים: \u0003מי כתיב\u0004 \u0005[האם כתוב]\u0006 ש\u0003בנו\u0004 מתחלל? \u0003\"זרעו\" כתיב\u0004 \u0005[נאמר]\u0006 ובכלל זרעו גם בתו, כאמור \u0003\"לא יחלל זרעו בעמיו\".\u0004 אבל בת בתו חללה שהיא כבר דור שלישי, מותרת מכוח הגזירה שווה.","ושואלים: אם כן \u0003בת בנו תישתרי\u0004 \u0005[תהיה מותרת]!\u0006 ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"לא יחלל זרעו\", מקיש\u0004 (משווה) הכתוב \u0003זרעו לו, מה הוא בתו פסולה, אף בנו\u0004 של הכהן הגדול \u0003בתו פסולה.\u0004 ושואלים: אם כן \u0003בת בתו תיתסר\u0004 \u0005[תאסר]\u0006 מאותו טעם, שכמו שבתו פסולה כך בת בתו מישראל פסולה! ומשיבים: \u0003אם כן\u0004 אתה אומר שגם בת בתו פסולה, \u0003גזירה שוה\u0004 מ\"לא יטמא בעל בעמיו\" שלמדים ממנה דין חילול רק לזכרים \u0003מאי אהני ליה\u0004 \u0005[מה הועילה לו]?\u0006 אלא באה ללמד שבת בתו כשירה.","שנינו במשנה שה\u0003חלל שנשא בת ישראל\u0004 — \u0003בתו פסולה\u0004 לכהונה. ותוהים: \u0003הא תנא ליה רישא\u0004 \u0005[הרי\u0006 כבר \u0005שנה\u0006 דבר \u0005זה\u0006 \u0005בתחילה]\u0006 \u0003\"בת חלל זכר פסולה מן הכהונה לעולם\"!\u0004 ומשיבים: \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בראשה]\u0006 של הפיסקה \u0003ישראל שנשא חללה, תנא נמי סיפא\u0004 \u0005[שנה גם כן בסופה]\u0006 \u0003חלל שנשא בת ישראל\u0004 כדי להשלים את הענין.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' דוסתאי בן יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' דוסתאי בן יהודה אומר: כשם שבני ישראל מקוה טהרה לחללות,\u0004 כלומר, שחללה שנישאה לבן ישראל בטל מזרעה איסור חללות ובתה כשירה לכהונה, \u0003כך בנות ישראל מקוה טהרה לחללים\u0004 ובנותיהם כשירות. ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' דוסתאי בר' יהודה?\u0004 ומסבירים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא יחלל זרעו בעמיו\",\u0004 לומר: \u0003בעם אחד הוא דמיחל\u0004 \u0005[שמחלל],\u0006 כאשר גם הוא וגם אשתו חללים, אבל \u0003בשני עממים אינו מיחל\u0004 \u0005[מחלל]\u0006 וישראל לענין זה נחשבים לגבי כהנים כעם אחר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ממה שנאמר \u0003\"לא יחלל זרעו\" אין לי אלא זרעו\u0004 שמתחלל, ואולם \u0003היא עצמה,\u0004 האשה שבא עליה כהן באיסור, \u0003מנין\u0004 שנפסלת לכהונה? \u0003אמרת\u0004 (אומר אתה): \u0003קל וחומר,\u0004 \u0003מה זרעו שלא עבר עבירה\u0004 — \u0003מתחלל, היא שעברה עבירה\u0004 — \u0003אינו דין שמתחללת?\u0004","ומקשים: \u0003הוא,\u0004 הכהן \u0003עצמו יוכיח, שעבר עבירה ואין מתחלל,\u0004 שלמרות שנאסר בעבודה כשהוא נשוי לה, הרי כאשר נפרד ממנה — נעשה שוב כשר. ודוחים: \u0003מה להוא,\u0004 לכהן עצמו, \u0003שכן אין\u0004 איש \u0003מתחלל בכל מקום,\u0004 שהרי לא מצאנו דוגמה שכהן מתחלל או נפסל על ידי ביאה אסורה, \u0003תאמר בהיא,\u0004 באשה, \u0003שמתחללת בכל מקום,\u0004 כגון שבא עליה פסול שהיא נעשית זונה ופסולה לכהונה לעולם.","\u0003ואם נפשך לומר\u0004 ולטעון כנגד סברה זו שאמרנו, הרי יש לכך ראיה אחרת: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא יחלל זרעו\",\u0004 וכוונת הדברים: \u0003לא יחולל זה שהיה כשר ונתחלל,\u0004 שלשון חילול אינה מתאימה לזרעו, שהרי מעולם לא היה כשר, אלא בא ללמד על האשה שבא עליה באיסור שמת חילה היתה כשירה ולכן אפשר לומר עליה שמתחללת.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הענין של \u0003\"אם נפשך לומר\",\u0004 מה היה הנימוק שאפשר היה לומר כנגד הסברה שנאמרה מתחילה? ומסבירים: \u0003וכי תימא איכא למיפרך\u0004 \u0005[ואם תאמר יש\u0006 מקום \u0005לפרוך],\u0006 לשבור את ההשוואה: \u0003מה לזרעו\u0004 — \u0003שכן יצירתו בעבירה,\u0004 ולכן אין ללמוד מכאן לגבי האשה — וכנגד טענה זו \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא יחלל\", לא יחולל\u0004 — \u0003זה שהיה כשר ונתחלל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזו היא חללה\u0004 — \u0003כל שנולדה מן הפסולים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פסולים\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003פסולים לו,\u0004 שהאשה אסורה לאדם זה מטעם קירבה או מטעם אחר, \u0003הרי מחזיר גרושתו\u0004 אחרי שנישאה לאחר ש\u0003פסולה לו ו\u0004בכל זאת \u0003בניה כשרים, דכתיב\u0004 \u0005[שנאמר]\u0006 בענין זה \u0003\"תועבה היא\"\u0004 (דברים כד, ד) ואנו למדים מן ההדגשה של \"היא\" לומר: \u0003היא תועבה, ואין בניה תועבים,\u0004 שהם כשרים לגמרי!","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003איזו היא חללה\u0004 — \u0003כל שנולדה מן פסול כהונה.\u0004 ותוהים: \u0003נולדה\u0004 — \u0003אין\u0004 \u0005[כן].\u0006 \u0003לא נולדה\u0004 — \u0003לא?\u0004 ו\u0003הרי אלמנה,\u0004 או \u0003גרושה,\u0004 או \u0003זונה\u0004 שנבעלו לכהן, ש\u0003לא נולדה\u0004 מפסול כהונה \u0003וקא הויא\u0004 \u0005[והריהי]\u0006 \u0003חללה!\u0004","\u0003אמר רבה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003איזו חללה מוזכרת שלא היה לה שעת הכושר כלל,\u0004 שמלידתה היתה פסולה — \u0003כל שנולדה מן פסול כהונה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מוזכרת\",\u0004 היכן היא מוזכרת? \u0003אמר רב יצחק בר אבין: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003איזו היא חללה שעיקרה מדברי תורה ואין צריכין לפרש\u0004 ולדרוש בענין זה \u0003מדברי סופרים\u0004 — \u0003כל שנולדה מן פסולי כהונה\u0004 שבמפורש נאמר \"לא יחלל זרעו\", אבל זו שבא עליה כהן באיסור איננה מוזכרת בתורה, ונלמדה מדברי סופרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כהן גדול אם נשא \u0003אלמנה אלמנה אלמנה\u0004 — \u0003אינו חייב\u0004 מלקות \u0003אלא אחת.\u0004 וכן \u0003גרושה גרושה גרושה\u0004 — \u0003אינו חייב אלא אחת.\u0004","אם נשא אשה שהיא גם \u0003אלמנה ו\u0004גם \u0003גרושה ו\u0004גם \u0003חללה\u0004 וגם \u0003זונה, בזמן שהם כסדר,\u0004 שכך אירעו הדברים שקודם התאלמנה ואחר כך נישאה לאחר ונתגרשה, ואחר כך נישאה לכהן ונתחללה, ואחר כך בא עליה גוי או איסור ערוה ונעשתה זונה — \u0003חייב\u0004 מלקות \u0003על כל אחת ואחת\u0004 מן העבירות הללו בכל פעם שבא עליה. ואולם אם \u0003זינתה\u0004 תחילה \u0003ו\u0004אחר כך \u0003נתחללה\u0004 על ידי ביאת כהן שנישאת לו, \u0003ו\u0004אחר כך \u0003נתגרשה,\u0004 ונישאה לאחר \u0003ונתארמלה\u0004 (נתאלמנה) — \u0003אינו חייב\u0004 כהן גדול הנושא אותה \u0003אלא אחת.\u0004","ומבארים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אלמנה אלמנה אלמנה אינו חייב אלא אחת.\u0004 ושואלים: \u0003האי\u0004 \u0005[זו]\u0006 \u0003אלמנה\u0004 שאמרנו שלוש פעמים \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שבא\u0004 על שלוש אלמנות, \u0003על אלמנת ראובן, ועל אלמנת שמעון, ועל אלמנת לוי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו חייב אלא אחת?\u0004"],["\u0003הרי גופין מוחלקים,\u0004 כלומר, כל אחת מאלה היא גוף לעצמו, \u0003הרי שמות מוחלקים,\u0004 שבכל אחת יש שם של איסור לעצמו וברור שילקה על כל ביאה!","\u0003אלא\u0004 תאמר \u0003שבא על אלמנה אחת שלש ביאות.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 בין ביאה לביאה — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ש\u0003אינו חייב אלא אחת,\u0004 שהרי אינו לוקה אלא לאחר התראה, והתראה אחת היתה לשלוש הביאות ואין בכך שום חידוש.","\u0003אלא\u0004 תאמר \u0003דאתרו ביה אכל חדא וחדא\u0004 \u0005[שהתרו בו על כל אחת ואחת]\u0006 מן הביאות — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו חייב אלא אחת? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נזיר שהיה שותה יין כל היום כולו\u0004 — \u0003אינו חייב\u0004 משום שתיית יין \u0003אלא אחת\u0004. \u0003אמרו לו \"אל תשתה\" \"אל תשתה\" והוא שותה\u0004 — \u0003חייב על כל אחת ואחת,\u0004 על כל שתיה שלאחר התראה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003שבא\u0004 פעם אחת \u0003על אלמנת ראובן שהיתה\u0004 קודם \u0003אלמנת שמעון שהיתה\u0004 קודם \u0003אלמנת לוי. מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הרי\u0004 כאן \u0003שמות מוחלקים,\u0004 שהרי היא אלמנה משלושה בעלים וילקה שלוש פעמים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003גופים מוחלקים בעינן\u0004 \u0005[צריכים אנו]\u0006 כדי להענישו בכמה עונשים \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 ולכן לוקה רק פעם אחת.","שנינו שאם בא על \u0003\"אלמנה וגרושה וחללה זנה\"\u0004 (ויקרא כא, יד) — חייב על כולן אם היה זה לפי הסדר הזה. ושואלים: \u0003האי תנא מאי קסבר\u0004 \u0005[תנא זה מה\u0006 הוא \u0005סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 ש\u0003איסור חל על איסור,\u0004 שאם חל איסור על חפץ או אדם יכול גם איסור נוסף לחול עליו, אם כן \u0003איפכא נמי\u0004 \u0005[ההיפך גם כן],\u0006 שגם אם היתה תחילה זונה ואחר כך נתחללה יהיו בה כל אותם איסורים! \u0003ואי קסבר\u0004 \u0005[ואם סבור\u0006 הוא\u0005]\u0006 ש\u0003אין איסור חל על איסור\u0004 — \u0003אפילו כסדר הזה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא!\u0004","\u0003אמר רבא: האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003איסור חל על איסור\u0004 בכלל \u0003לית ליה\u0004 \u0005[אין לו]\u0006 ולדעתו אין איסור חל על איסור, אבל \u0003איסור מוסיף אית ליה\u0004 \u0005[יש לו],\u0006 שאם האיסור השני יש בו תוספת לגבי האיסור הראשון — אזי חל איסור על איסור. כיצד?","\u0003אלמנה אסורה לכהן גדול ושריא\u0004 \u0005[ומותרת]\u0006 \u0003לכהן הדיוט.\u0004 כיון ש\u0003הויא לה\u0004 \u0005[נעשתה]\u0006 \u0003גרושה, מיגו דאיתוסף לה איסורא\u0004 \u0005[מתוך שנוסף לה איסור]\u0006 \u0003לגבי כהן הדיוט\u0004 — \u0003איתוסף לה איסורא\u0004 \u0005[נוסף לה\u0006 גם \u0005איסור]\u0006 \u0003לגבי כהן גדול, ועדיין שריא למיכל\u0004 \u0005[מותרת\u0006 היא \u0005לאכול]\u0006 \u0003בתרומה\u0004 אם היא בת כהן. אם \u0003הויא לה\u0004 \u0005[נהייתה]\u0006 \u0003חללה\u0004 על ידי ביאת כהן, \u0003מיגו דאיתוסף איסורא\u0004 \u0005[מתוך שנוסף איסור]\u0006 עליה, שאסורה \u0003למיכל\u0004 \u0005[לאכול]\u0006 \u0003בתרומה, איתוסף איסורא\u0004 \u0005[נוסף\u0006 בה \u0005איסור]\u0006 חללה גם \u0003לגבי כהן גדול\u0004 שבא עליה נוסף על איסור אלמנה וגרושה שיש עליה, לכן רק לפי הסדר הזה חייב על כולן, אבל בסדר אחר — לא.","אך יש לשאול \u0003אלא זונה מאי\u0004 \u0005[מה]\u0006 \u0003איסור מוסיף אית\u0004 \u0005[יש]\u0006 \u0003בה?\u0004 שאין איסור יתר בזונה מאשר בחללה! \u0003אמר רב חנא בר רב קטינא: הואיל ושם זנות פוסל בישראל,\u0004 כלומר, אף שזונה בהגדרה המדוייקת שלה לענין כהונה (אשה שנבעלה לפסול לה) אינה אסורה אלא לכהנים, ואין בה תוספת על איסור חללה, מכל מקום שם זנות במשמעות הרחבה שלה, כגון לגבי אשת איש שזנתה — פוסל בישראל, שאשה כזו נאסרת לבעלה. ומתוך שאפשר לראות בכך איסור נוסף הריהו חל גם על איסור חללה.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת\u0004 ברייתא זו: \u0003כל שהוא ב\"יקח\",\u0004 כלומר, כל אשה הכלולה בנשים שעליהן חל האמור בכהן גדול \"בתולה מעמיו יקח\" (שם, יד), אם נושא אשה כגון זו כשהיא אלמנה או גרושה \u0003הרי הוא\u0004 עובר \u0003ב\"לא יקח\". כל שאינו ב\"יקח\" אינו ב\"לא יקח\", פרט לכהן גדול שבא על אחותו\u0004 שהיתה \u0003אלמנה,\u0004 שהואיל ואסורה עליו משום אחותו בהיותה בתולה ואינה ב\"יקח\", אין הוא מתחייב עליה משום \"לא יקח\" אם נשא אותה כשהיא אלמנה או גרושה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003דאמר\u0004 \u0005[\u0006זה \u0005שאמר]\u0006 \u0003לך,\u0004 זה ששנה ברייתא זו, \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 בכלל: \u0003אין איסור חל על איסור\u0004 ומשום כך אין אחותו האסורה עליו כבר, נאסרת ב\"לא יקח\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: האוכל נבילה ביום הכפורים פטור\u0004 מכרת על אכילה של יום הכיפורים, מכיון שחל עליו קודם איסור אכילה של נבילה. \u0003דאי רבנן\u0004 \u0005[שאם\u0006 שיטת \u0005חכמים\u0006 היא\u0005],\u0006 \u0003הא אמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]:\u0006 \u0003איסור חל על איסור.\u0004","ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהברייתא לענין \"יקח\" כדברי \u0005חכמים],\u0006 \u0003כי אמרי רבנן\u0004 \u0005[כאשר אמרו חכמים]\u0006 ש\u0003איסור חל על איסור\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כשהאיסור השני הוא \u0003איסור חמור\u0004 ואז הוא חל \u0003על איסור קל\u0004 (כגון איסור יום הכיפורים על איסור נבילה), \u0003אבל איסור קל על איסור חמור\u0004 — \u0003לא חייל\u0004 \u0005[אינו חל]\u0006 וכאן איסור אחותו שעונשו כרת חמור מאיסור \"אלמנה... לא יקח\" שעונשו מלקות.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך אמר לו רב ששת: \u0003הא מני\u0004 \u0005[זו\u0006 שיטת \u0005מי היא]\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003איסור חל על איסור. וכי אמר\u0004 \u0003י רבנן\u0004 \u0005[וכאשר אומרים חכמים]\u0006 \u0003איסור חל על איסור, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003איסור חמור\u0004 שחל \u0003על איסור קל, אבל איסור קל על איסור חמור\u0004 — \u0003לא חייל\u0004 \u0005[אינו חל].\u0006 \u0003דאי\u0004 \u0005[שאם\u0006 לשיטת\u0005]\u0006 \u0003ר' שמעון\u0004 — \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אפילו \u0003איסור חמור על איסור קל לא חייל\u0004 \u0005[אינו חל],\u0006 \u0003איסור קל על איסור חמור מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינו חל? והרי אין כאן כל חידוש!","ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003איסור כהונה שאני\u0004 \u0005[שונה],\u0006 שיש בו איסורים מרובים ומיוחדים, ושמא בכהנים יחול איסור על איסור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בזה פוטר ר' שמעון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ישראל הבא על אחותו\u0004 — ברור לנו כי \u0003זונה משוי לה\u0004 \u0005[עושה\u0006 הוא \u0005אותה]\u0006 ואסורה לכהן, שהרי נבעלה לזה שאסורה לו. אבל האם \u0003חללה משוי לה\u0004 \u0005[עושה\u0006 הוא \u0005אותה]\u0006 וכהן הבא עליה חייב גם משום חללה, \u0003או לא משוי לה\u0004 \u0005[אינו עושה אותה]\u0006 חללה?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003קל וחומר\u0004 הוא: \u0003מחייבי לאוין,\u0004 כאשר בא כהן על אשה האסורה לכהונה, שאיסורים אלה הם רק איסורי לאו, \u0003הויא\u0004 \u0005[נעשית היא]\u0006 \u0003חללה, מחייבי כריתות לא כל שכן\u0004 שתיעשה חללה? \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אין חללה אלא מאיסור כהונה? אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אין (איסור) חללה אלא מאיסור כהונה בלבד.\u0004","\u0003אמר רבא: מנא הא מילתא דאמור רבנן\u0004 \u0005[מניין דבר זה שאמרו חכמים]\u0006 \u0003אין חללה אלא מאיסור כהונה\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יאמר\u0004 במפורש איסור \u0003גרושה בכהן גדול ותיתי\u0004 \u0005[ותבוא,\u0006 תלמד\u0005]\u0006 הלכה זו \u0003בקל וחומר מכהן הדיוט, ואנא אמינא\u0004 \u0005[ו\u0006כך \u0005אני אומר]\u0006 מדעתי: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003לכהן הדיוט אסורה\u0004 גרושה, \u0003לכהן גדול מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 אם כן \u0003למה נאמרה\u0004 גרושה בכהן גדול — כדי ללמדנו: \u0003כשם שחלוקה גרושה מזונה וחללה בכהן הדיוט,\u0004 שיש בה איסור לאו בפני עצמו ללקות עליו — \u0003כך חלוקה בכהן גדול,\u0004 אם היתה גרושה וחללה.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, וכי \u0003מיגרע גרעה\u0004 \u0005[גרועה היא]\u0006 יותר? שהרי איסור זה חל עליו גם בהיותו כהן הדיוט ובודאי אינו בטל ממנו כשנעשה כהן גדול. \u0003אלא\u0004 כך צריך לומר: \u0003כשם שחלוקה גרושה מזונה וחללה בכהן הדיוט\u0004 וחייב על כל אחת בנפרד — \u0003כך אלמנה חלוקה מגרושה וחללה זונה בכהן גדול,\u0004 שלמרות שנאמרו בלאו אחד, יש בה איסור מיוחד לעצמו.","ועוד יש לשאול: \u0003חללה למה נאמרה\u0004 בכהן גדול? והרי נאסרה עליו אף בהיותו הדיוט! אלא באה חזרה זו ללמד כי \u0003אין חללה אלא מאיסור כהונה. זונה למה נאמרה\u0004 בכהן גדול כיון שהיא אסורה גם בכהן הדיוט? — \u0003נאמר כאן\u0004 בכהן גדול איסור על \u0003\"זנה\"\u0004 (ויקרא כא, יד), \u0003ונאמר להלן\u0004 בכהן הדיוט איסור על \u0003\"זנה\"\u0004 (שם ז), \u0003מה כאן\u0004 בכהן גדול הבא על הזונה \u0003זרעו חולין,\u0004 כלומר, חלל (שנאמר: \"ולא יחלל זרעו\". שם טו), \u0003אף להלן\u0004 בכהן הדיוט \u0003זרעו חולין,\u0004 כלומר, חלל.","\u0003אמר רב אשי: הילכך\u0004 \u0005[על כן],\u0006 \u0003כהן הבא על אחותו\u0004"],["\u0003זונה משוי לה\u0004 \u0005[עושה\u0006 הוא \u0005אותה],\u0006 כיון שנבעלה לפסול לה, ואולם \u0003חללה לא משוי לה\u0004 \u0005[אינו עושה אותה],\u0006 כי פסולה אינו משום איסור כהונה אלא בגלל איסור ערוה. אם \u0003חזר\u0004 אחיה, או כהן אחר \u0003ובא עליה\u0004 — \u0003עשאה\u0004 על ידי ביאה זו \u0003חללה,\u0004 שהוא חוזר ופוסלה בתורת כהן הבא על הזונה.","\u0003אמר רב יהודה: כהן גדול באלמנה לוקה שתים,\u0004 שני עונשי מלקות: \u0003אחת משום\u0004 שעבר על הלאו \u0003\"לא יקח\"\u0004 (ויקרא כא, יד) \u0003ואחת משום \"לא יחלל\"\u0004 (שם טו), שמחלל את האשה שבא עליה. ושואלים: \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 עונש מלקות שלישי \u0003משום \"לא יחלל זרעו\",\u0004 שהרי בניו ממנה הם חללים! ומשיבים: מדובר \u0003בשלא גמר ביאתו,\u0004 שאינו ראוי להוליד בביאה זו, ולכן אינו לוקה משום חילול זרעו אלא רק על זה שחילל אותה בביאתו זו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על דברי רב יהודה \u0003רבא\u0004 ממה ששנינו: כהן גדול הבא על \u0003אלמנה ו\u0004שהיתה קודם לכן \u0003גרושה\u0004 — \u0003לוקה משום שני שמות\u0004 (איסורים), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003שני שמות ותו לא\u0004 \u0005[ולא עוד]!\u0006 משמע שלוקה רק אחת משום אלמנה ואחת משום גרושה!","ודוחים: \u0003לא, שני שמות על זה,\u0004 שלוקה פעמיים משום אלמנה (משום \"לא יקח\" ומשום \"לא יחלל\") \u0003ושני שמות על זה,\u0004 שלוקה פעמיים משום גרושה (משום \"גרושה... לא יקח\", ומשום \"לא יחלל\").","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: אם בא על \u0003גרושה וחלוצה\u0004 — \u0003אינו חייב אלא על אחת,\u0004 שעל חלוצה אינו לוקה לפי שאינה אסורה לו מן התורה. והרי לפי מה שאמרנו לוקה על גרושה שתים! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אינו חייב אלא על\u0004 עבירה \u0003אחת\u0004 של גרושה, \u0003ולעולם\u0004 חייב על אותה עבירה של גרושה שני עונשי מלקות משום \u0003שני שמות.\u0004","ושואלים: \u0003וחלוצה\u0004 אסורה לכהן רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר שאסור לכהן לשאת \u0003גרושה\u0004 — \u0003אין לי אלא גרושה, חלוצה מנין\u0004 — \u0003תלמוד לומר \"ואשה\u0004 גרושה\u0003\"\u0004 (ויקרא כא, ז), שבא לרבות גם חלוצה, שהיא מעין גרושה! ודוחים: אף על פי כן, איסור זה רק \u0003מדרבנן, וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב סמך בלבד]\u0006 הוא, ולא ראיה גמורה.","\u0003אמר אביי:\u0004 כהן ש\u0003קידש\u0004 אשה אסורה לו — \u0003לוקה, בעל\u0004 אשה אסורה — \u0003לוקה\u0004 מלקות נוספות. ומסבירים: אם \u0003קידש\u0004 — \u0003לוקה משום \"לא יקח\",\u0004 אם גם \u0003בעל\u0004 — \u0003לוקה משום \"לא יחלל\". רבא אמר:\u0004 אם \u0003בעל\u0004 — \u0003לוקה, לא בעל\u0004 — \u0003אינו לוקה\u0004 כלל. \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקח... ולא יחלל\", מה טעם\u0004 אמרו \u0003לא יקח\u0004 — \u0003משום לא יחלל\u0004 שאינו מתחייב בלקיחה (קידושין) בלבד בלא ביאה המביאה לחילול.","\u0003ו\u0004מעירים שלמרות שאביי סבור שיש איסור בקידושין בעצמם, \u0003מודה אביי ב\u0004אדם מישראל ה\u0003מחזיר גרושתו\u0004 לאחר שנישאה לאחר ונתגרשה או נתאלמנה, \u0003שאם קידש\u0004 אותה \u0003ולא בעל\u0004 — \u0003שאינו לוקה.\u0004 ומדוע — שכן \u0003\"לקחתה להיות לו לאשה\"\u0004 (דברים כד, ד) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 בענין זה, משמע שאין איסור בקידושין (\"לקחתה\") אלא אם כן היתה בהם אישות (\"לאשה\"), \u0003והא ליכא\u0004 \u0005[והרי אין כאן]\u0006 אישות, שהרי לא בא עליה.","\u0003ו\u0004מצד שני \u0003מודה רבא בכהן גדול באלמנה, שאם בעל ולא קידש\u0004 — \u0003שלוקה\u0004 גם על הבעילה בלבד, כי \u0003\"ולא יחלל זרעו בעמיו\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003והרי הוא חילל\u0004 אותה בביאתו. \u0003ושניהם מודים במחזיר גרושתו, שאם בעל ולא קידש\u0004 — \u0003שאינו לוקה,\u0004 משום \u0003דרך ליקוחין אסרה תורה\u0004 (כאמור \"לקחתה\"), ולא אסרה באיסור זה את הביאה בלבד.","שנינו במשנה ש\u0003ר' יהודה אומר: בת גר זכר\u0004 הריהי \u0003כבת חלל\u0004 זכר ואסורה לכהונה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בת גר זכר\u0004 הריהי \u0003כבת חלל זכר\u0004 ופסולה לכהונה. \u0003והדין\u0004 (בסברה, במידת קל וחומר) \u0003נותן\u0004 שנאמר כך: שהרי \u0003מה חלל, שבא מטפה כשרה,\u0004 ששני הוריו מישראל — בכל זאת \u0003בתו פסולה\u0004 לכהונה, \u0003גר שבא מטפה פסולה\u0004 של גוי — \u0003אינו דין שבתו פסולה\u0004 לכהונה?","ויש לדחות: \u0003מה לחלל, שכן יצירתו בעבירה,\u0004 מה שאין כן גר שלא היתה כל עבירה ביצירתו, ששני הוריו הגויים היו מותרים זה בזה. ויש לומר: \u0003כהן גדול באלמנה יוכיח, שאין יצירתו\u0004 של הבועל \u0003בעבירה\u0004 ובכל זאת \u0003בתו פסולה\u0004 לכהונה.","ודוחים: \u0003מה לכהן גדול באלמנה\u0004 — \u0003שכן ביאתו בעבירה\u0004 ולכן בתו פסולה! ויש לומר \u0003חלל יוכיח,\u0004 שאף שאין ביאתו בעבירה — בתו פסולה.","\u0003וחזר הדין,\u0004 שאפשר לדחות כל ראיה לעצמה ולחזור ולהתדיין בנושא זה הלוך ושוב, ו\u0003לא ראי זה כראי זה,\u0004 אין מקרה זה דומה לזה ולא זה דומה לזה, \u0003הצד השוה שבהן\u0004 — \u0003שאינן ברוב הקהל,\u0004 ששניהם יוצאים מכלל ישראל הכשרים, אם משום יצירתם או משום ביאתם בעבירה, והבת מהם פסולה לכהונה, \u0003אף אני אביא את הגר שאינו ברוב הקהל ו\u0004משום כך \u0003בתו פסולה.\u0004","ודוחים: \u0003מה להצד השוה שבהן\u0004 — \u0003שכן יש בהם צד עבירה,\u0004 מה שאין כן בגר!","ומתקנים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003כהן גדול באלמנה יוכיח, אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מצרי ראשון\u0004 שנשא גיורת מצרית \u0003יוכיח,\u0004 שאף שביאתו במצרית אינה בעבירה — מכל מקום הוולדות פסולים שרק אחרי שלושה דורות ראויים הם לבוא בקהל.","ויש לדחות: \u0003מה למצרי ראשון\u0004 — \u0003שכן אינו ראוי לבא בקהל\u0004 כלל. ויש לומר: \u0003חלל יוכיח\u0004 שהוא מותר לבוא בקהל ובכל זאת בתו פסולה לכהונה.","\u0003וחזר הדין,\u0004 שכן מחלל בלבד אי אפשר ללמוד, שהרי יצירתו בעבירה. \u0003לא ראי זה כראי זה, הצד השוה שבהן\u0004 — \u0003שאינן ברוב קהל, ובתו פסולה. אף אני אביא את הגר שאינו ברוב קהל ובתו פסולה.\u0004","ויש לדחות: \u0003מה להצד השוה שבהן\u0004 — \u0003שכן פוסלים\u0004 את הכהנת \u0003בביאתם\u0004 מה שאין כן בגר. \u0003ו\u0004על כך משיבים: \u0003רבי יהודה\u0004 אכן סבור: \u0003גר נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל בביאתו\u0004 את הכהנת, \u0003ומייתי לה\u0004 \u0005[ומביא,\u0006 לומד את הדבר הזה\u0005]\u0006 \u0003במה הצד מהאי דינא\u0004 \u0005[מתוך דין\u0006 קל וחומר \u0005זה]\u0006 מחלל.","שנינו במשנה ש\u0003ר' אליעזר בן יעקב אומר\u0004 ש\u0003גר\u0004 שנשא בת ישראל — בתו כשרה לכהונה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: גיורת פחותה מבת שלש שנים ויום אחד\u0004 — \u0003כשרה לכהונה, שנאמר\u0004 לאחר מלחמת מדין: \u0003\"וכל הטף בנשים... החיו לכם\"\u0004 (במדבר לא, יח), \u0003והלא פינחס\u0004 הכהן \u0003היה עמהם\u0004 והתיר הכתוב לכולם לקחת נשים אלו, משמע שהבנות הקטנות מותרות אף לכהנים. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? לדעתם \u0003\"החיו לכם\"\u0004 כוונתו \u0003לעבדים ולשפחות,\u0004 אבל לא לאישות.","ומעירים: \u0003וכולן,\u0004 כל התנאים שנחלקו במשנה, \u0003מקרא אחד דרשו:\u0004 שנאמר על הכהנים \u0003\"אלמנה וגרושה לא יקחו להם לנשים כי אם בתולת מזרע בית ישראל\"\u0004 (יחזקאל מד, כב); \u0003ר' יהודה סבר: עד דאית\u0004 \u0005[שיש]\u0006 \u0003כל זרע מישראל,\u0004 ולכן אם אחד מן ההורים הוא גר, אין זה נקרא מישראל. \u0003ר' אליעזר בן יעקב סבר: \"מזרע\u0004 ישראל \u0003\"\u0004משמע \u0003ואפילו מקצת זרע\u0004 ולכן אם אחד ההורים הוא ישראלי, הרי זה בכלל \"מזרע ישראל\".","\u0003ר' יוסי\u0004 האומר שאף בת של גר וגיורת מותרת לכהונה \u0003סבר: מי שנזרעו בישראל,\u0004 והרי בני גרים אף הם נזרעו ונוצרו כאשר היו בישראל. ואילו \u0003ר' שמעון בן יוחי\u0004 המכשיר גיורת בת פחות משלוש שנים ויום אחד \u0003סבר:\u0004 \"בתולות מזרע ישראל\" הכוונה \u0003מי שנזרעו בתוליה בישראל,\u0004 שמשעה שבתוליה נחשבים לעניין ביאה (בהיותה בת שלש) היתה כבר בישראל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרבא:\u0004"],["\u0003האי קרא\u0004 \u0005[פסוק זה]\u0006 שדרשו אותו התנאים, האמנם \u0003רישא\u0004 \u0005[ראשו]\u0006 מדבר \u0003בכהן גדול\u0004 (כאמור: \"כי אם בתולות\") \u0003וסיפא\u0004 \u0005[וסופו]\u0006 \u0003בכהן הדיוט\u0004 (שנאמר: \"והאלמנה אשר תהיה אלמנה מכהן יקחו\")?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 כך יש לפרש.","שאל אותו: \u0003וכתב קרא הכי\u0004 \u0005[ו\u0006האם \u0005המקרא נכתב כך],\u0006 שעוסק בפסוק אחד בשני נושאים שונים בלי להבדילם זה מזה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 וכיוצא בזה מצאנו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונר אלהים טרם יכבה ושמואל שכב בהיכל ה'\"\u0004 (שמואל א ג, ג), וכמשמעו מקרא זה תמוה — איך ייתכן ששמואל שכב בהיכל? \u0003והלא אין\u0004 רשות \u0003ישיבה בעזרה אלא למלכי בית דוד בלבד,\u0004 וכל שכן שכיבה! \u0003אלא\u0004 כך צריך לפרש את הכתוב: \u0003\"\u0004ו\u0003נר אלהים טרם יכבה\"\u0004 — \u0003בהיכל ה', \"ושמואל שכב\"\u0004 — \u0003במקומו\u0004 מחוץ לעזרה.","כיון שהזכרנו את הפסוק ביחזקאל דנים בו עוד, נאמר שם (מד, כב) \u0003\"והאלמנה אשר תהיה אלמנה מכהן יקחו\"\u0004 משמע: אלמנה \u0003מכהן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אלמנה \u0003מישראל לא?!\u0004 ותמוה שיש כאן הלכה שאין כיוצא בה בתורה! אלא \u0003הכי קאמר\u0004 \u0005[כך אומר]:\u0006 \u0003מכהן יקחו\u0004 כוונתו — \u0003משאר כהנים יקחו,\u0004 כלומר, שאר הכהנים שאינם כהן גדול מותרים לשאת אלמנה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 מה שנאמר \u0003\"מכהן יקחו\"\u0004 כוונתו — \u0003משאר כהנים יקחו.\u0004","\u0003ר' יהודה אומר\u0004 יש לפרש: \u0003מן המשיאים\u0004 (המיוחסים) \u0003לכהונה יקחו.\u0004 ומעירים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שדרש את תחילת הפסוק \"מזרע ישראל\", ו\u0003אמר: בת גר זכר כבת חלל זכר,\u0004 ועל כך ממשיך ודורש את הפסוק ואומר: \u0003כל שאתה נושא\u0004 את \u0003בתו\u0004 — \u0003אתה נושא\u0004 את \u0003אלמנתו, וכל שאי\u0004 (אין) \u0003אתה נושא\u0004 את \u0003בתו\u0004 כגון גר \u0003אי אתה נושא אלמנתו,\u0004 שהכהן רשאי לשאת רק אלמנה של זה שבתו מותרת לכהן.","שנינו במשנה ש\u0003ר' יוסי אומר\u0004 ש\u0003אף גר שנשא גיורת\u0004 בתו כשרה לכהונה. \u0003אמר רב המנונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: הלכה כר' יוסי וכן אמר רבה בר בר חנה: הלכה כר' יוסי. ומיום שחרב בית המקדש נהגו כהנים סילסול\u0004 (הידור) \u0003בעצמן\u0004 והחמירו \u0003כ\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 שאין נושאים בת גרים אלא אם כן אחד ההורים הוא ישראל.","\u0003אמר רב נחמן, אמר לי\u0004 רב \u0003הונא:\u0004 אם הכהן \u0003בא לימלך\u0004 (להתייעץ) אם לשאת אשה זו או לא — \u0003מורים לו\u0004 לנהוג למעשה \u0003כר' אליעזר בן יעקב\u0004 שלא יישאנה, ואם \u0003נשא\u0004 אותה — \u0003אין מוציאים אותה ממנו, כר' יוסי,\u0004 שהרי אמרנו שהלכה כמותו.","\u0003האומר \"בני זה ממזר\u0004 הוא \u0003\",\u0004 כגון שאומר שנולד מחייבי כריתות — \u0003אינו נאמן\u0004 לפוסלו. \u0003ואפילו שניהם,\u0004 האב והאם, \u0003מודים על העובר שבמעיה\u0004 של אשתו ש\u0003ממזר הוא\u0004 — \u0003אינם נאמנים. ר' יהודה אומר: נאמנים.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואפילו שניהם\",\u0004 מה החידוש שאפילו האם אינה נאמנת על כך, מדוע תיחשב עדותה טובה יותר משלו? ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]:\u0006 \u0003לא מיבעיא איהו\u0004 \u0005[נצרכה\u0006 לומר \u0005הוא]\u0006 ש\u0003לא קים ליה\u0004 \u0005[ברור לו],\u0006 שהרי אין האב יודע בוודאות אם הוולד הוא ממנו, \u0003אלא אפילו איהי דקים\u0004 \u0005[היא שברור]\u0006 \u0003לה\u0004 ממי הוולד — \u0003לא מהימנא\u0004 \u0005[אינה נאמנת].\u0006 \u0003ולא מיבעיא היכא דאית ליה\u0004 \u0005[נצרכה\u0006 לומר \u0005היכן שיש לו\u0006 לוולד\u0005]\u0006 כבר \u0003חזקה\u0004 של \u0003כשרות, דלא מהימני\u0004 \u0005[שאינם נאמנים],\u0006 \u0003אלא אפילו עובר נמי\u0004 \u0005[גם כן]\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 עדיין \u0003חזקה\u0004 של \u0003כשרות\u0004 בכל זאת \u0003לא מהימני\u0004 \u0005[אין\u0006 ההורים \u0005נאמנים].\u0006","שנינו במשנה: \u0003רבי יהודה אומר נאמנים.\u0004 ומסבירים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בענין בן בכור \u0003\"יכיר\"\u0004 (דברים כא, יז), וכוונתו — \u0003יכירנו לאחרים,\u0004 שנתנה תורה רשות ומהימנות לאב לומר מי הוא בנו הבכור. \u0003מכאן אמר ר' יהודה: נאמן אדם לומר \"זה בני בכור\". וכשם שנאמן אדם לומר \"זה בני בכור\", כך נאמן אדם לומר \"זה בן גרושה\" ו\"זה בן חלוצה\". וחכמים אומרים:\u0004 על אלה \u0003אינו נאמן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"יכיר\",\u0004 לומר שהוא נאמן להודיע מי הוא בנו ומי אינו בנו, \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 שבמשנה, \u0003\"יכיר\"\u0004 שהוסיף המקרא \u0003למה לי?\u0004","ומשיבים: \u0003בצריך הכירא\u0004 \u0005[היכר],\u0006 במקרה שלא ידוע מי מן הבנים הוא הבכור, שאז נאמר שסומכים על עדות אביו. ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 שייך הדבר — לגבי \u0003\"לתת לו פי שנים\"\u0004 (שם) בירושה? \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שסומכים על עדותו, וכי \u0003למה לי קרא\u0004 \u0005[כתוב]\u0006 כזה? הלא \u0003מגו דאי בעי מיתבא ליה\u0004 \u0005מתוך שאם היה רוצה לתת לו\u0006 נכסים אלו ב\u0003מתנה מי\u0004 \u0005[האם]\u0006 \u0003לא יהבי ליה\u0004 \u0005[היו נותנים לו]?\u0006 ולכן יש לקבל דבריו כשאומר שבנו זה בכור, שהרי הוא כנותן לו מתנה.","ומשיבים: מדובר כאן \u0003בנכסים שנפלו\u0004 בחלקו \u0003לאחר מיכן.\u0004 שבאותה שעה שאמר — לא היה יכול לתת אותם, ובכל זאת סומכים על עדותו.","ושואלים: \u0003ול\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר אדם מקנה דבר שלא בא לעולם,\u0004 וכיון שיכול לתת מראש את כל הנכסים שיבואו לו, במתנה, אם כן \u0003\"יכיר\" למה לי?\u0004 ומשיבים: \u0003שנפלו לו\u0004 הנכסים לאב \u0003כשהוא גוסס\u0004 שלא היה מסוגל להקנות אותם, ולכן נאמר \"יכיר\" שמכוח הכרת האב יכול להקנות אף נכסים אלה לבנו הבכור.","\u0003מי שנתן רשות לשלוחו לקדש את בתו, והלך הוא\u0004 האב \u0003וקדשה\u0004 בעצמו לאדם אחר, \u0003אם\u0004 קידושין \u0003שלו\u0004 שקידש את הבת \u0003קדמו\u0004 לקידושי השליח — \u0003קידושיו קידושין, ואם של שלוחו קדמו\u0004 — \u0003קידושיו\u0004 של השליח \u0003קידושין, ואם אינו ידוע\u0004 קידושיו של מי קדמו"],["\u0003שניהם,\u0004 שני האנשים שנתקדשה להם \u0003נותנים גט\u0004 כדי להתירה לאחר. \u0003ואם רצו\u0004 והסכימו ביניהם — \u0003אחד נותן גט, ואחד כונס\u0004 אותה לאשה.","\u0003וכן האשה שנתנה רשות לשלוחה לקדשה, והלכה\u0004 היא \u0003וקדשה את עצמה\u0004 לאדם אחר; \u0003אם\u0004 קידושיה \u0003שלה\u0004 שקיבלה בעצמה \u0003קדמו\u0004 — \u0003קדושיה\u0004 שלה \u0003קידושין, ואם של שלוחה קדמו\u0004 — \u0003קידושיו\u0004 שקידש אותה \u0003קידושין. ואם אינן יודעין\u0004 איזה מהם קדם — \u0003שניהם,\u0004 שני אלה שקידשו אותה \u0003נותנים לה גט, ואם רצו\u0004 — \u0003אחד נותן לה גט ואחד כונס.\u0004","\u0003וצריכא\u0004 \u0005[וצריך]\u0006 דין זה להיאמר הן לגבי המקדש את בתו והן לגבי האשה המקדשת את עצמה. \u0003דאי אשמעינן גבי דידיה\u0004 \u0005[שאם היה\u0006 האיש המקדש את בתו \u0005משמיע לנו\u0006 רק \u0005לגבי עצמו]\u0006 היינו אומרים \u0003משום דגברא קים ליה\u0004 \u0005[שהאיש מוחזק לו,\u0006 בקי\u0005]\u0006 \u0003ביוחסין,\u0004 וכאשר החליט לקדש את בתו לאדם מסויים היה בטוח בייחוסו, וכוונתו לבטל את שליחותו של השליח שמינה. \u0003אבל איתתא\u0004 \u0005[אשה]\u0006 ש\u0003לא קים\u0004 \u0005[מוחזק]\u0006 \u0003לה,\u0004 אינה בקיאה \u0003ביוחסין, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ניהוו\u0004 \u0005[יהיו]\u0006 \u0003קידושיה קידושין\u0004 גמורים והיא מקבלת עליה שקידושיו של השליח יתפסו.","\u0003ו\u0004להיפך, \u0003אי אשמעינן גבי דידה\u0004 \u0005[אם היה משמיע לנו\u0006 רק \u0005לגביה עצמה],\u0006 היינו אומרים: \u0003משום דאיתתא דייקא ומינסבא\u0004 \u0005[שאשה מדקדקת ונשאת],\u0006 שבודקת היטב מי הוא המקדש אותה ורק אחר כך מסכימה היא להינשא לו, וכשקידשה את עצמה ודאי בחרה את הבעל הרצוי לה. \u0003אבל איהו\u0004 \u0005[הוא,\u0006 האב\u0005]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 כל כך, ושמא נתן רשות יתירה לשליח, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדינים.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003קידשה אביה בדרך,\u0004 כשהיה מחוץ לעיר, \u0003ו\u0004בינתיים \u0003קידשה\u0004 היא את \u0003עצמה בעיר, והרי היא\u0004 עכשיו \u0003בוגרת. רב אמר: הרי היא בוגרת לפנינו\u0004 וכיון שהיא מוחזקת כבוגרת אין האב יכול לקדש אותה וקידושין שקידשה אביה אינם תופסים. \u0003ושמואל אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לקידושי שניהם.\u0004","ומבררים: \u0003אימת\u0004 \u0005[מתי]\u0006 היה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה \u0003בתוך ששה\u0004 חודשים שבין נערות לבגרות של הבת, \u0003בהא נימא\u0004 \u0005[\u0006האם \u0005בזה יאמר]\u0006 \u0003רב הרי היא בוגרת לפנינו?\u0004 הלא מסתבר לומר \u0003השתא\u0004 \u0005[\u0006רק \u0005עכשיו]\u0006 \u0003הוא\u0004 ש\u0003בגרה\u0004 וקודם היתה נערה, וקידושיו של האב תפסו, שהרי האב רשאי לקדש את בתו כשהיא נערה. \u0003אלא\u0004 תאמר שהיה הדבר \u0003לאחר ששה\u0004 חודשים מנערותה, וכי \u0003בהא נימא\u0004 \u0005[בזה יאמר]\u0006 \u0003שמואל: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לקידושי שניהם? והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל\u0004 עצמו: \u0003אין בין נערות לבגרות אלא ששה חדשים בלבד,\u0004 ואחר כך הריהי בוגרת ואין האב יכול לקדשה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דקדיש בההוא יומא דמשלים\u0004 \u0005[שקידש באותו יום שנגמרים]\u0006 בו \u0003ששה\u0004 חודשים אלה. \u0003רב אמר: הרי היא בוגרת לפנינו,\u0004 וטעמו: \u0003מדהשתא\u0004 \u0005[מ\u0006כיון \u0005שעכשיו]\u0006 היא \u0003בוגרת, בצפרא\u0004 \u0005[בבוקר]\u0006 כשקידש אותה האב \u0003נמי\u0004 \u0005[גם כן]\u0006 היתה \u0003בוגרת.\u0004 \u0003ושמואל אמר:\u0004 שמא רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דאייתי\u0004 \u0005[שהביאה]\u0006 \u0003סימנים\u0004 של בגרות, אבל כאשר קידש אותה האב ייתכן שהיתה עדיין נערה.","ושואלים: \u0003ו\u0004לדעת \u0003שמואל מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הדבר \u0003מ\u0004דין \u0003מקוה?\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה\u0004 שהיו בו ארבעים סאה כשיעור הראוי למקוה \u0003שנמדד ונמצא חסר\u0004 משיעורו — \u0003כל טהרות שנעשו על גביו,\u0004 כלומר, דברים טמאים שנטהרו על ידי טבילה במקוה זה \u0003למפרע, בין ברשות היחיד בין ברשות הרבים\u0004 — \u0003טמאות.\u0004 משמע שאנו דנים על העבר לפי המצב בשעת בדיקה וכמו כן לענייננו יש לומר שהיתה הבת בוגרת בשעת הקידושין!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 הדין במקוה \u0003דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003העמד טמא על חזקתו ואימר\u0004 \u0005[ואמור]\u0006 ש\u0003לא טבל\u0004 כראוי, ונשאר טמא ונמצא שיש חזקה אחרת המסייעת להנחה זו.","ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003העמד מקוה על חזקתו ואימר\u0004 \u0005[ואמור]\u0006 ש\u0003לא חסר\u0004 בזמן הטבילה אלא לאחר מכן. ומשיבים: \u0003הרי חסר לפניך\u0004 ובטלה החזקה. ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]:\u0006 \u0003הרי בוגרת לפניך!\u0004 ומשיבים, כאן יש לומר: רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא\u0004 ש\u0003בגרה.\u0004 ומקשים: אם כן \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 במקוה נאמר: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא\u0004 ש\u0003חסר,\u0004 ושמא זמן קצר קודם לא היה חסר.","ומשיבים: \u0003התם תרתי לריעותא\u0004 \u0005[שם\u0006 יש \u0005שני\u0006 טעמים \u0005להרע],\u0006 להחמיר בטהרות שנעשו על גביו: אחד — שהמקוה חסר לפנינו, ושנית — שיש לטמא חזקת טומאה. ואילו \u0003הכא חדא לריעותא\u0004 \u0005[כאן\u0006 יש רק סיבה \u0005אחת להרע]\u0006 את החזקה שהיתה נערה — שהיא בוגרת לפנינו.","ועוד שואלים: \u0003ו\u0004לדברי \u0003שמואל מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 דין זה \u0003מ\u0004דין \u0003חבית? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה בודק את החבית\u0004 אם יש בה יין כדי \u0003להפריש עליה תרומה, והולך,\u0004 שמייחד חבית זו שהיין בתוכה ומשתמש בו לשם תרומה על יינות טבל הבאים לידו עד שיהא כל היין שבחבית כולה תרומה, ואז יתננה לכהן, \u0003ואחר כך נמצאת\u0004 חבית זו של \u0003חומץ,\u0004 ואין יכול לתרום מחומץ על יין, ונמצא שלא היתה זו תרומה. \u0003כל שלשה ימים\u0004 אחר הבדיקה הראשונה \u0003ודאי\u0004 היה זה יין, ומה שהופרש עליו באותו זמן מתוקן הוא, \u0003מיכן ואילך,\u0004 יותר משלושה ימים אחרי הבדיקה — \u0003ספק\u0004 שמא כבר החמיץ.","\u0003ורמינן\u0004 \u0005[והשלכנו,\u0006 הראנו סתירה\u0005]\u0006 בין דין \u0003חבית\u0004 ודין \u0003מקוה:\u0004 \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003דהכא\u0004 \u0005[שכאן]\u0006 במקוה אומרים שהוא \u0003ודאי\u0004 טמא \u0003ומאי שנא דהכא\u0004 \u0005[ומה שונה שכאן\u0006 בחבית\u0005]\u0006 רק \u0003ספק\u0004 טבל?","\u0003ואמר רב חנינא מסוריא: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה \u0003חבית\u0004 — \u0003ר' שמעון היא,\u0004 של \u0003גבי מקוה נמי ספיקא משוי\u0004 \u0005[גם כן כספק\u0006 הוא \u0005רואה\u0006 את הדבר\u0005],\u0006 ולא כטמא ודאי.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל טהרות שנעשו על גביו\u0004 של המקוה שחסר \u0003למפרע, בין ברשות היחיד בין ברשות הרבים\u0004 — \u0003טמאות. ור' שמעון אומר:\u0004 שיש לדון בכך כבספק טומאה, ולכן \u0003ברשות הרבים טהורות\u0004 לפי הכלל שספק טומאה ברשות הרבים טהור, \u0003ברשות היחיד\u0004 — \u0003תולין,\u0004 שאם נגע הטמא בתרומה אין אוכלים אותו מפני הספק, אבל גם אין שורפים אותו כטמא.","\u0003אבל ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 אף בדין החבית הרי זה \u0003טבל למפרע,\u0004 שדנים לפי המצב כפי שהוא לפנינו, וקשה על דברי שמואל! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין החבית \u0003דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003העמד טבל על חזקתו\u0004 — \u0003ו\u0004כיון שהיה מתחילה בחזקת טבל \u0003אימר\u0004 \u0005[ואמור]\u0006 \u0003לא ניתקן.\u0004","ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003העמד יין על חזקתו, ואימר\u0004 \u0005[ואמור]\u0006 \u0003לא החמיץ!\u0004 ודוחים: דבר זה אי אפשר לומר ש\u0003הרי החמיץ לפניך!\u0004 ויש לשאול לענין בוגרת \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003הרי היא בוגרת לפנינו!\u0004 ודוחים: בנערה אפשר לומר רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא\u0004 ש\u0003בגרה.\u0004 ומקשים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר: \u0003השתא הוא דאחמיץ\u0004 \u0005[עכשיו הוא שהחמיץ]\u0006 ולא קודם!","ומסבירים: \u0003התם תרתי לריעותא\u0004 \u0005[שם\u0006 יש \u0005שני\u0006 גורמים \u0005לרעה],\u0006 אחד — שהוא חומץ לפנינו, ושנית — שיש חזקה לטבל מעיקרו. \u0003הכא חדא לריעותא\u0004 \u0005[כאן אחת לרעה]\u0006 \u0003הוא דאיכא\u0004 \u0005[שיש],\u0006 שבוגרת לפנינו, ולכן מעמידים אותה בחזקת נערה, לשיטת שמואל.","ומציעים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שמחלוקת זו של רב ושמואל היא \u0005כ\u0006מחלוקת \u0005תנאים];\u0006"],["\u0003מי מוציא מיד מי?\u0004","\u0003הוא מוציא מידם\u0004 נכסים שלו שהחזיקו אחרים בהם \u0003בלא\u0004 צורך להביא \u0003ראיה\u0004 שהיה אז שכיב מרע, \u0003והן אין מוציאים מידו,\u0004 כשהנכסים עדיין ברשותו, \u0003בלא ראיה\u0004 שהיה אז בריא, אלו \u0003דברי ר' יעקב. ר' נתן אומר: אם בריא הוא\u0004 עכשיו — \u0003עליו להביא ראיה שהיה שכיב מרע\u0004 בשעה שכתב להם את כל נכסיו, \u0003ואם שכיב מרע הוא\u0004 עכשיו — \u0003עליהם להביא ראיה שבריא היה\u0004 באותה שעה.","ומציעים: \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]:\u0006 \u0003רב\u0004 ש\u0003אמר כר' נתן\u0004 שדנים לפי המצב עכשיו, \u0003ושמואל\u0004 ש\u0003אמר כר' יעקב\u0004 המעמיד את השאלה בספק שמא היה שכיב מרע וממילא אין מוציאים מידו? ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול \u0003היה\u0004 \u0005לומר]\u0006 \u0003לך רב: אנא דאמרי\u0004 \u0005[אני\u0006 מה \u0005שאמרתי]\u0006 \u0003אפילו כר' יעקב,\u0004 כיון ש\u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יעקב התם\u0004 \u0005[שם]\u0006 כך אלא משום \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003העמד ממון על חזקתו\u0004 ושיישאר אצל מי שנמצא הממון ברשותו, \u0003אבל הכא מי נימא\u0004 \u0005[כאן,\u0006 בנערה שבגרה, \u0005הא\u0006 \u0005ם\u0006 אפשר \u0005לומר]\u0006 \u0003העמד גוף על חזקתו?!\u0004 והרי ברור לנו שהיא עומדת להיהפך לבוגרת!","\u0003ושמואל אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 \u0003אפילו ל\u0004דעת \u0003ר' נתן,\u0004 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' נתן התם\u0004 \u0005[שם]\u0006 שהולכים לפי המצב הנוכחי אלא משום \u0003דכולי עלמא\u0004 \u0005[שהכל]\u0006 \u0003בחזקת בריאים קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 \u0003מאן דקא מפיק נפשיה\u0004 \u0005[מי שמוציא\u0006 את \u0005עצמו]\u0006 \u0003מחזקה\u0004 וטוען שהיה שכיב מרע — \u0003הוי עליה לאיתויי\u0004 \u0005[הרי עליו להביא]\u0006 \u0003ראיה, אבל הכא מי קא מפקא נפשה מחזקה דקמיה\u0004 \u0005[כאן האם\u0006 היא \u0005מוציאה את עצמה מהחזקה שלפנינו]?\u0006 שהרי אין חזקה שתאמר שנערה זו היתה כבר בבוקר בוגרת.","ומציעים עוד: \u0003נימא כהני תנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שמחלוקת זו של רב ושמואל היא \u0005כתנאים אלה]\u0006 שדנו בבעיה זו: \u0003קידשה אביה בדרך וקידשה עצמה בעיר והרי היא בוגרת, תנא חדא\u0004 \u0005[שנה\u0006 בברייתא \u0005אחת]:\u0006 \u0003הרי היא בוגרת לפנינו\u0004 ולפיכך רק הקידושין שקידשה את עצמה חלים, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לקידושי שניהם. מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר — \u0003חד\u0004 \u0005[\u0006ברייתא \u0005אחת]\u0006 \u0003כרב וחד\u0004 \u0005[ו\u0006ברייתא \u0005אחת]\u0006 \u0003כשמואל?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003כ\u0004שיטת \u0003שמואל\u0004 הוא, אלא \u0003כאן במכחשתו\u0004 ואומרת שהיתה בוגרת קודם לקידושיו, \u0003כאן בשאין מכחשתו\u0004 וחוששים אנו מספק לקידושי שניהם.","ושואלים: אם כן \u0003ונימא מדמתניתא לא פליגי, אמוראי נמי לא פליגי\u0004 \u0005[ונאמר\u0006 גם \u0005כיון שהברייתות אינן חלוקות גם האמוראים,\u0006 רב ושמואל, \u0005אינם חלוקים]\u0006 ואחד מהם מדבר במכחישתו, ואחד בלא מכחישתו? ודוחים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור כן]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנשיא מ\u0004העיר \u0003דוויל עבד עובדא כוותיה\u0004 \u0005[עשה מעשה\u0006 בבעיה זו \u0005כשיטתו]\u0006 של \u0003רב,\u0004 שלא חש לקידושי האב \u0003ואיקפיד\u0004 \u0005[והקפיד]\u0006 \u0003שמואל ואמר\u0004 בלגלוג: \u0003כולי עלמא כיילי ליה בקבא זוטא\u0004 \u0005[כל העולם מודדים להם\u0006 חכמה \u0005במידה קטנה]\u0006 \u0003והאי מדרבנן כיילי ליה בקבא רבה\u0004 \u0005[וזה מהחכמים מדדו לו במידה גדולה]?\u0006 כלומר, שכעס עליו שהעיז פנים ופסק במחלוקת זו שלא הוכרעה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 כלל, \u0003אמאי קא מקפיד\u0004 \u0005[מדוע מקפיד היה]\u0006 שמואל?","\u0003דילמא כי עבד עובדא\u0004 \u0005[שמא כאשר\u0006 רב יוסף \u0005עשה\u0006 את \u0005המעשה]\u0006 היה זה \u0003במכחשתו,\u0004 שאף שמואל מודה בכך. אלא ודאי נחלקו רב ושמואל בדבר, ומה שעשה רב יוסף היה זה כשלא הכחישתו, ולכן הקפיד שמואל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אמימר: הילכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003שמואל. ורב אשי\u0004 עצמו \u0003אמר: הילכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב.\u0004 ומסכמים: \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב.\u0004","\u0003מי שיצא הוא ואשתו למדינת הים, ובא\u0004 (חזר) \u0003הוא ואשתו ובניו ואמר: \"אשה שיצאת עמי למדינת הים\u0004 — \u0003הרי היא זו, ואלו בניה\"\u0004 — \u0003אין צריך להביא ראיה לא על האשה\u0004 שכשירה היא, שכבר נבדקה בזמן נישואיה \u0003ולא על הבנים\u0004 שהם בניו וכשרים הם. אם חזר בלי האשה, ואמר \u0003\"מתה\u0004 אשתי \u0003ואלו בניה\"\u0004 — \u0003מביא ראיה על הבנים\u0004 שהם בני אשתו זו, \u0003ואינו מביא ראיה על האשה.\u0004","אבל אם בא ממדינת הים ואמר \u0003\"אשה נשאתי במדינת הים הרי היא זו, ואלו בניה\"\u0004 — \u0003מביא ראיה על האשה\u0004 שכשירה היא \u0003ואין צריך להביא ראיה על הבנים.\u0004 אם אמר \u0003\"\u0004נשאתי אשה במדינת הים ו\u0003מתה ואלו בניה\"\u0004 — \u0003צריך להביא ראיה על האשה ועל הבנים.\u0004","\u0003אמר רבה בר רב הונא: וכולן,\u0004 כל שאמרו על בנים שאין צריך להביא ראיה עליהם, מדובר \u0003בכרוכים אחריה,\u0004 בבנים קטנים הכרוכים אחר האשה ונוהגים עימה כבנים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר אדם \u0003\"אשה נשאתי במדינת הים\"\u0004 — \u0003מביא ראיה על האשה\u0004 שכשירה היא, \u0003ואין צריך להביא ראיה על הבנים. ומביא ראיה על\u0004 הבנים \u0003הגדולים, ואין צריך להביא ראיה על הקטנים\u0004 שרואים שהם כרוכים אחרי אימם, ומן הסתם בניה הם. \u0003במה דברים אמורים\u0004 — \u0003ב\u0004שאמר \u0003\"אשה אחת\u0004 נשאתי \u0003\",\u0004 \u0003אבל ב\u0004שאמר שנשא \u0003שתי נשים\u0004 במדינת הים — \u0003מביא ראיה על האשה ועל הבנים, על הגדולים ועל הקטנים\u0004 אף שכרוכים אחרי האשה הכשירה, שמא בניה של השניה הם וזו מגדלת אותם.","\u0003אמר ריש לקיש:\u0004"],["\u0003לא שנו\u0004 שסומכים אנו על כך שהבנים כרוכים אחריה \u0003אלא בקדשי הגבול\u0004 (תרומה), שאם היתה אשת כהן בניה רשאים לאכול בתרומה, \u0003אבל ביוחסין\u0004 להשיא את בנותיהם לכהנים \u0003לא\u0004 סומכים על כך. \u0003ור' יוחנן אמר: אפילו ביוחסין,\u0004 שהואיל וכרוכים אחריה, נחשבים הם כבניה לכל דבר.","מעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מלקין\u0004 אדם שהעידו בו שעבר עבירה \u0003על\u0004 פי \u0003החזקות,\u0004 אפילו כשאין עדות בדבר, וכן \u0003סוקלין ושורפין על\u0004 פי \u0003החזקות, ואין שורפין תרומה על\u0004 פי \u0003החזקות\u0004 אלא כשיש עדות. כיצד?","\u0003מלקין על החזקות\u0004 — \u0003כ\u0004שיטת \u0003רב יהודה.\u0004 ש\u0003אמר רב יהודה:\u0004 אם אשה \u0003הוחזקה נדה\u0004 בין \u0003שכינותיה,\u0004 אם \u0003בעלה\u0004 בא עליה — \u0003לוקה עליה משום נדה,\u0004 שמאחר שהיתה לה חזקת נדה אין צורך בעדות גמורה שהיתה נדה.","\u0003סוקלין ושורפין על החזקות\u0004 — \u0003כ\u0004דברי \u0003רבה בר רב הונא.\u0004 ש\u0003אמר רבה בר רב הונא: איש ואשה תינוק ותינוקת שהגדילו בתוך הבית\u0004 כמשפחה אחת — \u0003נסקלין זה על זה,\u0004 אם בא התינוק על האשה — סוקלים אותם משום בן שבא על אמו, \u0003ונשרפין זה על זה,\u0004 אם האיש בא על התינוקת, משום ערות בת אשתו.","\u0003אמר ר' שמעון בן פזי, אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: מעשה באשה שבאת לירושלים ותינוק מורכב לה על כתיפה\u0004 כבן, \u0003והגדילתו ו\u0004לבסוף \u0003בא עליה, והביאום לבית דין וסקלום\u0004 משום ערות האם. \u0003לא מפני שבנה ודאי\u0004 שהרי לא היתה עדות בזה, \u0003אלא מפני שכרוך אחריה\u0004 וחזקה שהוא בנה.","\u0003ואין שורפין תרומה על\u0004 פי \u0003החזקות\u0004 — ש\u0003אמר ר' שמעון בן לקיש: שורפין\u0004 תרומה \u0003על\u0004 פי \u0003החזקות, ור' יוחנן אומר: אין שורפין\u0004 על פי החזקות. ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 הם \u0005לטעמם,\u0006 לשיטתם\u0005]\u0006 בענין זה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003תינוק\u0004 טמא \u0003שנמצא בצד העיסה\u0004 הטהורה \u0003ובצק בידו\u0004 שיש לחשוש שהוא נטל מן העיסה הזו, \u0003ר' מאיר מטהר\u0004 את העיסה לפי שאין הוכחה שהתינוק נגע בה, ושמא אדם אחר נתנה לו. \u0003וחכמים מטמאין, מפני שדרכו של תינוק לטפח\u0004 בידיו בכל מיני אשפה, ומצוי שיהיה שם שרץ מת או דבר טמא אחר.","\u0003והוינן\u0004 \u0005[והיינו\u0006 עסוקים\u0005]\u0006 \u0003בה,\u0004 בבעיה זו: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר?\u0004 — \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003רוב תינוקות מטפחין\u0004 בעיסה המצויה לידם, \u0003ומיעוט אין מטפחין, ועיסה\u0004 כשלעצמה \u0003בחזקת טהרה עומדת\u0004 שהרי לא נודע שנטמאה, \u0003וסמוך מיעוטא\u0004 \u0005[וצרף\u0006 את \u0005מיעוט]\u0006 התינוקות שאינם מטפחים \u0003לחזקה\u0004 של העיסה ועל ידי צירוף זה של טעמים \u0003איתרע ליה רובא\u0004 \u0005[הורע\u0006 כוחו של \u0005רוב]\u0006 התינוקות המטפחים, ולכן אין לטמא את העיסה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים: \u0003מיעוטא כמאן דליתא דמי\u0004 \u0005[מיעוט נחשב כמי שאינו],\u0006 שכשיש רוב מבטלים לגמרי את המיעוט, ומשום כך יש רק ניגוד בין \u0003רובא\u0004 \u0005[רוב]\u0006 תינוקות שהם טמאים \u0003וחזקה\u0004 של טהרת העיסה, ובמקרה כזה \u0003רובא\u0004 \u0005[הרוב]\u0006 \u0003עדיף.\u0004","\u0003אמר ריש לקיש משום\u0004 (בשם) \u0003ר' אושעיא:\u0004 הלכה \u0003זו\u0004 בתינוק \u0003היא\u0004 דוגמא של חזקה \u0003ששורפין עליה את התרומה,\u0004 שלדעת חכמים הדבר ברור וודאי עד כדי לשרוף. \u0003ר' יוחנן אמר: אין זו חזקה ששורפין עליה תרומה\u0004 אלא תולים (משאירים אותה ללא הכרעה, בלא לאכול ובלי לשרוף).","ושואלים: \u0003אלא איזו חזקה לר' יוחנן ששורפין עליה את התרומה?\u0004 ומשיבים: \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 היתה \u0003עיסה בתוך הבית, ושרצים\u0004 שמטמאים במותם \u0003וצפרדעים\u0004 שאינם מטמאים \u0003מטפלין\u0004 (מצויים) \u0003שם, ונמצאו חתיכות\u0004 של בעל חיים בלתי ידוע \u0003בעיסה. אם רוב\u0004 היצורים שבבית היו \u0003שרצים\u0004 — \u0003טמאה\u0004 העיסה, משום שיש להניח שיש בה חלק משרץ. \u0003אם רוב צפרדעים\u0004 — \u0003טהורה.\u0004 ובכגון זה, שהרוב נמצא לפנינו, סומכים על החזקה שהיו שם רוב שרצים אפילו לשרוף.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 שאמרו: \u0003שני דברים אין בהם דעת לישאל,\u0004 שאי אפשר לשאול ולברר אותם, מה אירע. וכלל בידינו שבמקרה כזה כאשר אי אפשר לברר את הדבר, ספק טומאה אפילו ברשות היחיד — טהור שלא ככל ספק טומאה ברשות היחיד, שטמא, \u0003ו\u0004בכל זאת \u0003עשאום חכמים כמה שיש בהם דעת לישאל\u0004 וטימאום מפני הספק: \u0003תינוק, ועוד\u0004 הלכה \u0003אחרת.\u0004","\u0003תינוק\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 ביחס לתינוק שנמצא בצד העיסה, שאי אפשר לשאול את העיסה אם נטמאה או לא. \u0003ועוד אחרת מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — ששנינו: \u0003עיסה\u0004 טהורה שהיתה \u0003בתוך הבית, ו\u0004היו \u0003תרנגולים ומשקים טמאים\u0004 מצויים \u0003שם, ונמצאו\u0004"],["\u0003נקורים נקורים\u0004 (חורים קטנים) \u0003בעיסה\u0004 שנקרו בה התרנגולים — במקרה זה \u0003תולין,\u0004 כלומר, \u0003לא אוכלין ולא שורפין\u0004 אותה, לפי שאין הוכחה שהתרנגולים שתו קודם הניקור מן המשקה הטמא והיות ואין בהם דעת לישאל, אין שורפין מספק, וכר' יוחנן.","\u0003אמר ר' יהושע בן לוי: לא שנו אלא במשקים\u0004 טמאים \u0003לבנים,\u0004 שאין הוכחה ממראה הניקורים אם התרנגולים הביאו מהמשקין שבעיסה. \u0003אבל במשקים\u0004 טמאים \u0003אדומים, אם איתא דנקיר מידע ידיע\u0004 \u0005[יש\u0006 מקום לומר \u0005שנקרו\u0006 — הרי הדבר \u0005ידוע]\u0006 שאם הביאו מהמשקים היו הניקורים צריכים להיות עם סימני אודם. ושואלים: \u0003ודילמא בלעתינהו\u0004 \u0005[ושמא בלעה אותם]\u0006 ה\u0003עיסה\u0004 את המשקים, ואין הצבע ניכר?","\u0003אמר ר' יוחנן: דבר זה שמע בריבי\u0004 (אדם גדול), כלומר, ר' יהושע בן לוי, \u0003ופירושו לא שמע\u0004 והיה עליו לפרט יותר: \u0003לא שנו אלא במשקים צלולים\u0004 שעשויים להבלע בעיסה בלא להשאיר סימן. ומה נקראים צלולים — \u0003שבבואה\u0004 (דמות) של תינוק \u0003ניכר בה\u0004 במשקה אם מסתכל בו. \u0003אבל משקים עכורים\u0004 — \u0003לא.\u0004 שאם היה מן המשקים בעיסה היו נשארים סימנים כלשהם.","\u0003לא יתייחד אדם עם שתי נשים\u0004 שמא יבוא איתן מתוך כך לידי עבירה, \u0003אבל אשה אחת מתייחדת עם שני אנשים. ר' שמעון אומר: אף איש אחד מתייחד עם שתי נשים בזמן שאשתו עמו, וישן עמהם\u0004 אם היו עימו שתי נשים \u0003ב\u0004אותו \u0003פונדקי\u0004 (פונדק), \u0003מפני שאשתו משמרתו\u0004 שלא יזנה עימן. ועוד אמרו: \u0003מתייחד אדם עם אמו ועם בתו וישן עמהם בקירוב בשר\u0004 בלי בגדים ואין חוששים לעריות אלה. \u0003ואם הגדילו\u0004 הבן או הבת — \u0003זו ישנה בכסותה וזה ישן בכסותו,\u0004 אבל מותר להם לישון במיטה אחת.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמרו שלא יתייחד עם שתי נשים אבל אשה מתייחדת עם שני אנשים? \u0003תנא דבי\u0004 \u0005[שנה בבית]\u0006 \u0003אליהו:\u0004 \u0003הואיל ונשים דעתן קלות עליהן\u0004 ונוחות להתפתות.","שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שהייחוד אסור? \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: רמז ל\u0004איסור \u0003יחוד מן התורה מנין\u0004 — \u0003שנאמר\u0004 בענין מסית לעבודה זרה: \u0003\"כי יסיתך אחיך בן אמך\"\u0004 (דברים יג, ז).","ויש להבין מדוע נקטה התורה בדוגמה \"בן אמך\", \u0003וכי\u0004 רק \u0003בן אם מסית, בן אב אינו מסית? אלא לומר לך: בן מתייחד עם אמו\u0004 ויכול להיות עימה בכל עת, ומשום כך אם היו לאם שני בנים מבעלים שונים הריהם כרוכים עם אימם ומתוך כך הם מתיידדים זה עם זה, ולכן נקטה התורה \"בן אמך\" מפני שהם קרובים זה לזה. אבל עם בן אביו בלבד, מכיוון שיש לאב אשה אחרת אסור לבן להתייחד עימה, ואינו מגיע לקירבה זו עם בן אביו. \u0003ואסור להתייחד עם כל עריות שבתורה.\u0004","ושואלים: מה שפירשנו היה רמז לענין יחוד, אבל \u0003פשטיה דקרא במאי כתיב\u0004 \u0005[פשוטו של כתוב במה\u0006 הוא \u0005נאמר,\u0006 עוסק\u0005],\u0006 מדוע מודגש בו \"בן אמך\"? \u0003אמר אביי:\u0004 בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר\u0006 הכתוב\u0005];\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 \u0003בן אב דסני ליה\u0004 \u0005[ששונא אותו]\u0006 \u0003ועייץ ליה\u0004 \u0005[ויועץ לו]\u0006 \u0003עצות רעות\u0004 כיון שהם יריבים זה לזה לענין הירושה, \u0003אלא אפילו בן אם,\u0004 ש\u0003לא סני ליה\u0004 \u0005[שונא אותו],\u0006 שהרי אין ביניהם סכסוך ממון מצד ירושה משותפת שהרי כל אחד מהם יורש את אביו שלו — \u0003אימא צייתי ליה\u0004 \u0005[אמור שיקשיב לו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף לזה לא ישמע אם הוא מסיתו.","ומעירים: \u0003נימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003אבא שאול, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 תינוק שמת, \u0003כל שלשים יום\u0004 ללידתו — אין עושים לו לוויה ממש אלא \u0003יוצא בחיק\u0004 שנושאים אותו בחיקם \u0003ונקבר\u0004 על ידי \u0003אשה אחת ושני אנשים, אבל לא\u0004 על ידי \u0003איש אחד ושתי נשים\u0004 משום איסור ייחוד. \u0003אבא שאול אומר: אף באיש אחד ושתי נשים.\u0004 משמע שהוא מתיר להתייחד עם שתי נשים!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהמשנה שלנו כדעת \u0003אבא שאול,\u0004 מתיר הוא בברייתא משום ש\u0003בשעת אנינות תביר יצריה\u0004 \u0005[שבור יצרו]\u0006 של אדם ואין לחשוש שמא יבוא לחטא.","\u0003ורבנן סברי לה\u0004 \u0005[וחכמים סבורים]\u0006 בענין זה \u0003כר' יצחק.\u0004 ש\u0003אמר ר' יצחק\u0004 על הכתוב \u0003\"מה יתאונן אדם חי גבר על חטאו\"\u0004 (איכה ג, לט) — \u0003אפילו בשעת אנינותו של אדם\u0004 (\"יתאונן אדם\") — \u0003יצרו מתגבר עליו\u0004 (\"גבר על חטאיו\"). ושואלים: \u0003ואבא שאול\u0004 מה הוא אומר על ראיה זו? משיבים: \u0003כי כתיב ההוא\u0004 \u0005[כאשר נאמר אותו\u0006 כתוב\u0005]\u0006 — \u0003במתרעם על מדותיו,\u0004 דרכיו של הקדוש ברוך הוא \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש לפרש את הכתוב: \u0003מה יתרעם\u0004 אדם \u0003על מדותיו\u0004 של הקדוש ברוך הוא לומר שנוהג עימו שלא כדין, \u0003וכי גבר\u0004 (התגבר, ניצח) \u0003על חטאיו? דיו חיים שנתתי לו\u0004 ואין מגיע לו יותר מזה.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 חוששים גם בשעת אבל \u0003כי ההוא מעשה דההיא איתתא דהוה עובדא ואפיקתיה\u0004 \u0005[כאותו מעשה באשה אחת שהיה מעשה והוציאה אותו]\u0006 את בעלה מקברו, לאחר שזנתה עם אדם אחר, כדי לחפות על התרשלותו של הנואף עימה בשמירה על תלוי המלכות. ומכאן ראיה שאף בשעת אבילות אין לסמוך על שבירת היצר.","שנינו במשנה: \u0003אבל אשה אחת\u0004 מתייחדת עם שני אנשים. \u0003אמר רב יהודה אמר רב: לא שנו\u0004 דבר זה \u0003אלא ב\u0004אנשים \u0003כשרים, אבל בפרוצים\u0004 — \u0003אפילו בי\u0004 (יחד עם) \u0003עשרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תתייחד. \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מעשה\u0004 פעם, \u0003והוציאוה עשרה\u0004 אנשים לאשה אחת כדרך שמוציאים את המת לקבורה \u0003במטה\u0004 וזנו איתה. \u0003אמר רב יוסף: תדע\u0004 שכן הוא, \u0003דמיחברי בי עשרה וגנבי כשורא ולא מיכספי מהדדי\u0004 \u0005[ש\u0006הרי \u0005מתחברים יחד עשרה\u0006 אנשים \u0005וגונבים קורה\u0006 כבדה \u0005ואינם מתביישים זה מזה].\u0006 וכיוצא בזה יכולים להתחבר כמה אנשים יחד לשם זנות ואינם מתביישים זה מזה.","ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממשנה זו, שאמרו שמי שחושד באשתו כסוטה, וכשמביאה להשקותה מים המרים בבית המקדש \u0003מוסרין לו שני תלמידי חכמים\u0004 ללוותו, \u0003שמא יבא עליה בדרך,\u0004 שכן כל עוד לא נבדקה היא אסורה על בעלה. ונדייק מכאן: שני \u0003תלמידי חכמים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אינשי דעלמא\u0004 \u0005[סתם אנשים]\u0006 — \u0003לא,\u0004 משמע שלענין יחוד אין סומכים על סתם אנשים. ודוחים: משם אין ראיה לענין זה, אלא \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003תלמידי חכמים דידעי\u0004 \u0005[ש\u0006הם \u0005יודעים]\u0006"],["\u0003לאתרויי ביה\u0004 \u0005[להתרות בו]\u0006 שאסור לו לבוא עליה, שאם יבוא עליה אין המים בודקים אותה.","\u0003אמר רב יהודה אמר רב: לא שנו\u0004 ששנים יכולים להתייחד עם אשה, \u0003אלא בעיר\u0004 שמצויים אנשים, \u0003אבל בדרך\u0004 — \u0003עד שיהיו שלשה.\u0004 ומדוע אין די בשנים — \u0003שמא יצטרך אחד מהם להשתין\u0004 ויפנה הצידה \u0003ונמצא\u0004 שבאותה שעה \u0003אחד\u0004 בלבד \u0003מתייחד עם הערוה.\u0004 ומציעים: \u0003נימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003מוסרים לו שני תלמידי חכמים שמא יבא עליה בדרך. תרי ואיהו\u0004 \u0005[שנים והוא,\u0006 הבעל\u0005]\u0006 \u0003הא תלתא\u0004 \u0005[הרי שלשה],\u0006 משמע שבדרך צריכים שלושה. ומשיבים: משם אין ראיה, \u0003התם כי היכי דניהוו עליה סהדי\u0004 \u0005[שם\u0006 יש צורך בשנים נוספים \u0005כדי שיהיו עליו עדים],\u0006 שיעידו אם בא עליה בדרך.","מסופר: \u0003רב ורב יהודה הוו קאזלי באורחא\u0004 \u0005[היו הולכים בדרך],\u0006 \u0003הוה קאזלא ההיא אתתא קמייהו\u0004 \u0005[היתה מהלכת אשה אחת לפניהם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב יהודה: דל כרעיך\u0004 \u0005[הרם רגליך]\u0006 ומהר ללכת \u0003מקמי\u0004 \u0005[מפני]\u0006 \u0003גיהנם,\u0004 שלא נתייחד איתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 ש\u0003בכשרים שפיר דמי\u0004 \u0005[מותר הדבר]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי יימר\u0004 \u0005[אמר]\u0006 שמדובר \u0003בכשרים כגון אנא ואת\u0004 \u0005[אני ואתה]!\u0006 אמר לו רב יהודה: \u0003אלא כגון מאי\u0004 \u0005[מה]?\u0006 אמר לו: \u0003כגון ר' חנינא בר פפי וחביריו,\u0004 שלמרות פיתויים שהיו להם עמדו בנסיון ולא חטאו, אבל אדם אחר אינו נאמן בכך.","\u0003אמר רב: מלקין על ייחוד,\u0004 שאם התייחד אדם עם אשה מלקין אותו שעבר על איסור יחוד \u0003ו\u0004אולם \u0003אין אוסרין\u0004 אשה על בעלה, או פנויה להינשא לכהן \u0003על הייחוד,\u0004 שאין מניחים שבודאי נבעלה. \u0003אמר רב אשי: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה שמלקים \u0003אלא בייחוד\u0004 עם אשה \u0003פנויה, אבל בייחוד\u0004 של \u0003אשת איש\u0004 — \u0003לא.\u0004 ומדוע? \u0003שלא תהא מוציא לעז על בניה\u0004 שאם ילקוה יחשבו הכל שזנתה וילעיזו על בניה שהם ממזרים. והיא לא נענשה אלא על הייחוד בלבד.","מספרים\" \u0003מר זוטרא מלקי\u0004 \u0005[היה מלקה]\u0006 גם את המתייחד עם אשת איש, \u0003ו\u0004היה \u0003מכריז\u0004 מדוע הוא עושה כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן מפרהטיא לרב אשי: מר נמי לילקי ולכריז\u0004 \u0005[אדוני גם כן שילקה ויכריז]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אני חושש לעשות כן, שמא \u0003איכא דשמע בהא ולא שמע בהא\u0004 \u0005[יש שישמע בזו ולא ישמע בזו],\u0006 כלומר, שישמע שהלקו, ולא ישמע את ההכרזה שהלקאה זו היא משום יחוד בלבד.","\u0003אמר רב: מלקין על לא טובה השמועה,\u0004 לא רק על עובדות בדוקות, אלא גם כאשר יוצא שם רע על אדם שעובר עבירות, \u0003שנאמר: \"אל בני כי לוא טובה השמעה\"\u0004 (שמואל א ב, כד). \u0003מר זוטרא\u0004 כשהיה מוצא אדם שיצא עליו שם רע, \u0003מותיב לה אפסירה על כתפיה\u0004 \u0005[היה שם רסן\u0006 של חמור \u0005על כתפיו]\u0006 \u0003ומקרי ליה\u0004 \u0005[ו\u0006היה \u0005מקריא לו]\u0006 בשעת המלקות: \u0003\"אל בני\u0004 כי לא טובה השמועה\u0003\"\u0004 להודיע לרבים על מה הוא לוקה.","\u0003אמר רבה:\u0004 אשה ש\u0003בעלה בעיר\u0004 — \u0003אין חוששין משום ייחוד\u0004 עימה, מפני שחוששים הם לעבור עבירה, שאינם יודעים מתי יחזור הבעל. \u0003אמר רב יוסף:\u0004 אם היה \u0003פתח פתוח לרשות הרבים\u0004 — \u0003אין חוששין משום ייחוד.\u0004 מסופר: \u0003רב ביבי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב יוסף. בתר דכרך ריפתא\u0004 \u0005[אחרי שאכל]\u0006 בערב \u0003אמר להו\u0004 \u0005[להם]\u0006 רב יוסף לאנשי ביתו: \u0003שקולי דרגא מתותי\u0004 \u0005[הוציאו את המדרגות,\u0006 הסולם, \u0005מתחת]\u0006 \u0003ביבי\u0004 שהיה ישן בעליה, כלומר, שלא יוכל רב ביבי לרדת, משום איסור ייחוד עם אשת רב יוסף. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה:\u0004 אשה ש\u0003בעלה בעיר אין חוששין משום ייחוד!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב ביבי דשושבינתיה הואי וגייסא ביה\u0004 \u0005[ש\u0006אשת רב יוסף \u0005ידידתו היתה והיתה רגילה בו],\u0006 ולכן יש לחשוש יותר.","\u0003אמר רב כהנא:\u0004 כאשר \u0003אנשים\u0004 (גברים) נמצאים \u0003מבחוץ,\u0004 בחדר החיצוני, \u0003ונשים מבפנים,\u0004 בחדר פנימי — \u0003אין חוששין משום ייחוד\u0004 אם נכנס אחד מן האנשים למקום הנשים, לפי שרואים אותו חבריו כשנכנס. אבל אם היו \u0003אנשים\u0004 \u0003מבפנים ונשים מבחוץ\u0004 — \u0003חוששין משום ייחוד\u0004 שמא יאמר שיוצא לצורך אחר ויתייחד עם הנשים.","ומעירים: \u0003במתניתא תנא איפכא\u0004 \u0005[בברייתא שנה ההיפך],\u0006 שאם אנשים מבחוץ ונשים מבפנים חוששים שמא יכנס אחד מהאנשים פנימה בלא שירגישו בו. ואם אנשים מבפנים ונשים מבחוץ — אין חוששים ליחוד. מכיון שדרך הפנימיים החוצה עוברת דרך הנשים ויחשוש שמא יצא אחד האנשים אחריו. \u0003אמר אביי: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר רב כהנא הכי\u0004 \u0005[כך]\u0006 \u0003ותנא מתניתא איפכא\u0004 \u0005[ושנויה\u0006 ב\u0005ברייתא להיפך],\u0006 \u0003אנא נעביד לחומרא\u0004 \u0005[אנו נעשה לחומרה]\u0006 ונחמיר לחשוש בשני המקרים.","\u0003אביי דייר גולפי\u0004 \u0005[היה מסדר שורות\u0006 של \u0005קנקנים]\u0006 בין גברים לנשים שלא יוכלו לעבור ממקום למקום בלי להשמיע רעש. \u0003רבא דייר קנה\u0004 \u0005[\u0006היה \u0005מסדר שורות קנים]\u0006 שלא יוכלו לעבור. \u0003אמר אבין: סקבא דשתא ריגלא\u0004 \u0005[הפצע,\u0006 מקום התורפה \u0005של השנה\u0006 הוא \u0005הרגל]\u0006 משום שאז זמן שמחה, וגברים ונשים נפגשים ובאים לידי עבירה.","מסופר: \u0003הנך שבוייתא דאתאי\u0004 \u0005[אותן שבוי\u0006 \u0005ות שהובאו]\u0006 \u0003לנהרדעא\u0004 ונפדו שם. \u0003אסקינהו לבי\u0004 \u0005[העלות אותן לבית]\u0006 \u0003רב עמרם חסידא\u0004 \u0005[החסיד],\u0006 \u0003אשקולו דרגא מקמייהו\u0004 \u0005[הורידו\u0006 את \u0005המדרגות מפניהן]\u0006 שלא יוכלו גברים לעלות אליהן. \u0003בהדי דקא חלפה חדא מנייהו\u0004 \u0005[כאשר עברה אחת מהן]\u0006 ליד העליה \u0003נפל,\u0004 נעשה \u0003נהורא באיפומא\u0004 \u0005[אור בארובה]\u0006 משום שהיתה יפה ביותר. מתוך שחשק בה, \u0003שקליה\u0004 \u0005[לקח]\u0006 \u0003רב עמרם לדרגא\u0004 \u0005[את הסולם]\u0006 \u0003דלא הוו יכלין בי עשרה למדלייא, דלייא לחודיה\u0004 \u0005[שלא היו יכולים יחד עשרה\u0006 אנשים \u0005להרים אותו\u0006 ו\u0005הרים אותו לבדו],\u0006 \u0003סליק ואזיל\u0004 \u0005[\u0006ו\u0005היה\u0006 \u0005עולה והולך].\u0006","\u0003כי מטא לפלגא דרגא\u0004 \u0005[כאשר הגיע לחצי הסולם]\u0006 \u0003איפשח\u0004 \u0005[התחזק],\u0006 \u0003רמא קלא\u0004 \u0005[הרים\u0006 את \u0005קולו]\u0006 וצעק: \u0003נורא בי\u0004 \u0005[אש,\u0006 דליקה בוערת \u0005בבית]\u0006 \u0003עמרם!\u0004 כיון ששמעו שיש שריפה \u0003אתו רבנן\u0004 \u0005[באו חכמים]\u0006 וראו אותו עומד כך, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003כסיפתינן\u0004 \u0005[ביישת אותנו]\u0006 שהכל רואים מה רצית לעשות. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מוטב תיכספו בי\u0004 \u0005[תתביישו בבית]\u0006 \u0003עמרם בעלמא הדין\u0004 \u0005[בעולם הזה]\u0006 \u0003ולא תיכספו מיניה לעלמא דאתי\u0004 \u0005[תתביישו ממנו בעולם הבא].\u0006 \u0003אשבעיה דינפק מיניה\u0004 \u0005[השביע\u0006 את יצרו הרע \u0005שייצא ממנו],\u0006 \u0003נפק מיניה כי עמודא דנורא\u0004 \u0005[יצא ממנו\u0006 דבר \u0005כעמוד אש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ליצר הרע: \u0003חזי, דאת נורא ואנא בישרא, ואנא עדיפנא מינך\u0004 \u0005[ראה, שאתה אש ואני בשר, ואני עדיף ממך]\u0006 שהתגברתי עליך.","מסופר: כי \u0003ר' מאיר הוה\u0004 \u0005[היה]\u0006 \u0003מתלוצץ בעוברי עבירה,\u0004 שהיה אומר שאדם יכול בקלות להזהר מעבירה. \u0003יומא חד אידמי ליה\u0004 \u0005[יום אחד נדמה לו]\u0006 ה\u0003שטן כאיתתא בהך גיסא דנהרא\u0004 \u0005[כאשה\u0006 העומדת \u0005בצד האחר של הנהר],\u0006 \u0003לא הוה מברא\u0004 \u0005[היתה מעבורת]\u0006 לעבור את הנהר — \u0003נקט מצרא וקא עבר\u0004 \u0005[תפס בסולם החבלים ועבר]\u0006 את הנהר. \u0003כי מטא פלגא מצרא שבקיה\u0004 \u0005[כאשר הגיע לחצי החבל עזבו\u0006 היצר\u0005]\u0006 ו\u0003אמר\u0004 השטן והיצר לר' מאיר: \u0003אי לאו דקא מכרזי ברקיעא\u0004 \u0005[אם לא שמכריזים ברקיע]\u0006 \u0003\"הזהרו בר' מאיר ותורתו\" שויתיה לדמך תרתי מעי\u0004 \u0005[הייתי עושה את דמיך\u0006 כ\u0005שתי מעות],\u0006 כדבר חסר ערך, שהיית נופל ממדרגתך לגמרי.","ומסופר עוד: \u0003ר' עקיבא הוה\u0004 \u0005[היה]\u0006 \u0003מתלוצץ בעוברי עבירה. יומא חד אידמי ליה\u0004 \u0005[יום אחד נדמה לו]\u0006 ה\u0003שטן כאיתתא בריש דיקלא\u0004 \u0005[כאשה בראש הדקל].\u0006 \u0003נקטיה לדיקלא וקסליק ואזיל\u0004 \u0005[תפס בדקל והיה עולה והולך].\u0006 \u0003כי מטא לפלגיה דדיקלא שבקיה\u0004 \u0005[כאשר הגיע לחצי הדקל עזבו\u0006 היצר\u0005],\u0006 ו\u0003אמר\u0004 לו: \u0003אי לאו דמכרזי ברקיעא\u0004 \u0005[אם לא שמכריזים ברקיע]\u0006 \u0003\"הזהרו בר' עקיבא ותורתו\" שויתיה לדמך תרתי מעי\u0004 \u0005[הייתי עושה את דמיך\u0006 כ\u0005שתי מעות].\u0006","ועוד: החכם \u0003פלימו הוה\u0004 \u0005[היה]\u0006 \u0003רגיל למימר\u0004 \u0005[לומר]\u0006 \u0003כל יומא\u0004 \u0005[יום]:\u0006 \u0003גירא בעיניה\u0004 \u0005[חץ בעיניו]\u0006 של ה\u0003שטן,\u0004 שהיה צוחק מפיתויי היצר. \u0003יומא חד מעלי יומא דכיפורי הוה\u0004 \u0005[יום אחד ערב יום הכיפורים היה].\u0006 \u0003אידמי ליה כעניא\u0004 \u0005[נדמה לו\u0006 השטן \u0005כעני].\u0006 \u0003אתא קרא אבבא\u0004 \u0005[הלך\u0006 ו\u0005דפק בדלת]\u0006 כמבקש נדבה, \u0003אפיקו ליה ריפתא\u0004 \u0005[הוציאו לו לחם]\u0006 לאכול. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יומא כי האידנא כולי עלמא גואי ואנא אבראי\u0004 \u0005[יום כמו היום, הכל נמצאים בפנים\u0006 ואוכלים \u0005ואני\u0006 אעמוד \u0005בחוץ]\u0006 ואוכל? \u0003עייליה וקריבו ליה ריפתא\u0004 \u0005[הכניס אותו והביאו לו לחם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יומא כי האידנא כולי עלמא אתכא ואנא לחודאי\u0004 \u0005[יום כמו זה הכל\u0006 יושבים \u0005ליד השלחן ואני\u0006 יושב \u0005לבדי]?\u0006 \u0003אתיוהו אותבוהו אתכא\u0004 \u0005[הביאו אותו\u0006 ו\u0005הושיבו אותו ליד השלחן].\u0006 \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003מלא נפשיה שיחנא וכיבי עליה והוה קעביד ביה מילי דמאיס\u0004 \u0005[מלא את עצמו בשחין ומוגלה עליו והיה עושה בו,\u0006 בשלחן, \u0005דברים מאוסים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 פלימו לעני:"],["\u0003תיב שפיר\u0004 \u0005[שב יפה]\u0006 ואל תמאיס עצמך. ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 העני: \u0003הבו לי כסא\u0004 \u0005[תנו לי כוס],\u0006 \u0003יהבו ליה כסא\u0004 \u0005[נתנו לו כוס].\u0006 \u0003אכמר שדא ביה כיחו\u0004 \u0005[השתעל\u0006 ו\u0005השליך\u0006 בתוך הכוס \u0005את ליחתו]\u0006 היוצאת מגרונו. \u0003נחרו ביה\u0004 \u0005[גערו בו]\u0006 למה הוא עושה כן. \u0003שקא ומית\u0004 \u0005[עשה\u0006 עצמו \u0005כמת].\u0006 לאחר מכן \u0003שמעו דהוו קאמרי\u0004 \u0005[שמעו ש\u0006\u0005היו\u0006 אנשים \u0005אומרים]\u0006 מסביב: \u0003פלימו קטל גברא\u0004 \u0005[הרג אדם]!\u0006 \u0003פלימו קטל גברא\u0004 \u0005[הרג אדם]!\u0006 \u0003ערק וטשא נפשיה\u0004 \u0005[ברח\u0006 פלימו \u0005והחביא עצמו]\u0006 \u0003בבית הכסא. אזיל בתריה\u0004 \u0005[הלך\u0006 השטן \u0005אחריו],\u0006 \u0003נפל קמיה\u0004 \u0005[נפל\u0006 השטן \u0005לפניו].\u0006 \u0003כי דחזייה\u0004 \u0005[כאשר ראהו]\u0006 את פלימו \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003מצטער\u0004 ביותר \u0003גלי ליה נפשיה\u0004 \u0005[גילה לו\u0006 את \u0005עצמו]\u0006 שהוא השטן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 השטן: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמרת הכי\u0004 \u0005[כך]\u0006 \"חץ בעיניו של השטן\", וגרמת שהשטן יתגרה בך? אמר לו: \u0003ואלא היכי אימא\u0004 \u0005[איך אומר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לימא מר\u0004 \u0005[יאמר אדוני]\u0006 \u0003\"רחמנא נגער ביה\u0004 \u0005[הקדוש ברוך הוא יגער בו]\u0006 \u0003בשטן\".\u0004","מסופר: \u0003ר' חייא בר אשי הוה\u0004 \u0005[היה]\u0006 \u0003רגיל כל עידן דהוה נפל לאפיה\u0004 \u0005[כל זמן שהיה נופל על פניו]\u0006 בתפילה \u0003הוה אמר\u0004 \u0005[היה אומר]:\u0006 \u0003הרחמן יצילנו מיצר הרע. יומא חד שמעתינהו דביתהו\u0004 \u0005[יום אחד שמעה אותו אשתו\u0006 כשהתפלל כך\u0005]\u0006 \u0003אמרה: מכדי הא\u0004 \u0005[הואיל והרי]\u0006 \u0003כמה שני דפריש ליה מינאי\u0004 \u0005[כמה שנים שפרש ממני]\u0006 מחיי אישות בטענה שכבר אין לו כוח מחמת זיקנה, \u0003מאי טעמא קאמר הכי\u0004 \u0005[מה טעם\u0006 הוא \u0005אומר כך]\u0006 ומתפלל להנצל מיצר הרע?","\u0003יומא חדא הוה קא גריס בגינתיה\u0004 \u0005[יום אחד היה לומד בגינתו]\u0006 \u0003קשטה נפשה חלפה ותנייה קמיה\u0004 \u0005[קישטה את עצמה\u0006 ו\u0005חלפה ושנתה\u0006 וחזרה שוב \u0005לפניו].\u0006 \u0003אמר לה: מאן\u0004 \u0005[מי]\u0006 \u0003את?\u0004 \u0003אמרה: אנא חרותא דהדרי מיומא\u0004 \u0005[אני חרותא\u0006 (שם זונה אחת) \u0005שחוזרת מיום\u0006 העבודה שלי\u0005].\u0006 \u0003תבעה\u0004 \u0005[תבע אותה]\u0006 לתשמיש. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אייתי ניהליה להך רומנא דריש צוציתא\u0004 \u0005[הבא לי\u0006 כשכרי \u0005את הרימון הזה שבראש העץ].\u0006 \u0003שוור, אזל אתייה ניהלה\u0004 \u0005[קפץ, הלך\u0006 ו\u0005הביא אותו לה]\u0006 ובא עליה.","\u0003כי אתא לביתיה\u0004 \u0005[כאשר בא לביתו]\u0006 \u0003הוה קא שגרא דביתהו תנורא\u0004 \u0005[היתה מסיקה אשתו\u0006 את \u0005התנור],\u0006 \u0003סליק וקא יתיב בגויה\u0004 \u0005[עלה וישב בתוכו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 אשתו: \u0003מאי האי\u0004 \u0005[מהו זה]?\u0006 \u0003אמר לה: הכי והכי הוה\u0004 \u0005[כך וכך היה]\u0006 \u0003מעשה,\u0004 שהתפתתי לזנות. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אנא הואי\u0004 \u0005[אני הייתי\u0006 זו\u0005].\u0006 \u0003לא אשגח\u0004 \u0005[השגיח]\u0006 \u0003בה,\u0004 שחשב שהיא מנחמת אותו לשוא, \u0003עד דיהבה ליה סימני\u0004 \u0005[שנתנה לו סימנים]\u0006 שהיתה זאת היא. \u0003אמר לה: אנא מיהא לאיסורא איכווני\u0004 \u0005[אני על כל פנים לאיסור התכוונתי].\u0006 ומספרים: \u0003כל ימיו של אותו צדיק היה מתענה\u0004 על עבירה זו שעבר במחשבת איסור \u0003עד שמת באותה מיתה\u0004 מחמת הצער.","ומניין שמי שיש בו כוונה לעשות איסור נענש כאילו עבר עבירה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 מה שנאמר \u0003\"אישה הפרם וה' יסלח לה\"\u0004 (במדבר ל, יג), \u0003במה הכתוב מדבר\u0004 שצריכה האשה סליחה כאשר הופר הנדר על ידי בעלה — \u0003באשה שנדרה בנזיר, ושמע בעלה והפר לה, והיא לא ידעה שהפר לה בעלה, והיתה שותה יין ומטמאה למתים.\u0004","ומסופר: \u0003ר' עקיבא כי הוה מטי להאי פסוקא, הוה בכי\u0004 \u0005[כאשר היה מגיע לפסוק זה, היה בוכה],\u0006 \u0003אמר: ומה מי שנתכוין לאכול בשר חזיר\u0004 כמו אשה זו, שהתכוונה לאיסור \u0003ועלה בידו בשר טלה\u0004 (בשר כשר ומותר), ולא חטאה, שהרי הנדר הופר לה, בכל זאת \u0003אמרה תורה: צריכה כפרה וסליחה\u0004 (\"ה' יסלח לה\"), \u0003מי שנתכוין לאכול בשר חזיר ועלה בידו בשר חזיר\u0004 — \u0003על אחת כמה וכמה\u0004 שצריך סליחה וכפרה.","\u0003כיוצא בדבר אתה אומר \"ולא ידע ואשם ונשא עונו\"\u0004 (ויקרא ה, יז). \u0003כשהיה ר' עקיבא מגיע לפסוק זה היה בוכה: ומה מי שנתכוין לאכול שומן\u0004 (דבר מותר) \u0003ועלה בידו\u0004 בטעות \u0003חלב\u0004 — \u0003אמרה תורה \"ולא ידע ואשם ונשא עונו\",\u0004 שנחשב הדבר לעוון וצריך כפרה, \u0003מי שנתכוין\u0004 מתחילה \u0003לאכול חלב ועלה בידו חלב\u0004 — \u0003על אחת כמה וכמה. איסי בן יהודה אומר\u0004 על הכתוב \u0003\"ולא ידע ואשם ונשא עונו\"\u0004 — \u0003על דבר זה ידוו\u0004 (יכאבו) \u0003כל הדווים\u0004 (המצטערים, הכואבים), שהרי הכתוב מלמדנו שאדם נענש אפילו על דבר שלא ידע שחטא בו.","שנינו במשנה ש\u0003מתייחד אדם עם אמו. אמר רב יהודה אמר רב אסי: מתייחד אדם עם אחותו\u0004 בחדר אחד, \u0003ודר עם אמו ועם בתו\u0004 בקביעות באותו בית ואינו חושש. \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמרה\u0004 (אמר אותה) \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל, אמר\u0004 שמואל: \u0003אסור להתייחד עם כל עריות שבתורה, ואפילו עם בהמה,\u0004 שאף היא אסורה משום ערוה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מתייחד אדם עם אמו ועם בתו וישן עמהם בקירוב בשר, ו\u0004אם כן הרי זו \u0003תיובתא\u0004 \u0005[וקושיה חמורה]\u0006 לדברי \u0003שמואל!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך שמואל:\u0004 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 יש להביא קושיה מ\u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחותו וחמותו ושאר כל עריות שבתורה\u0004 כולל אמו ובתו \u0003אין מתייחד עמהם אלא בעדים.\u0004 ונדייק: \u0003בעדים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בעדים\u0004 — \u0003לא.\u0004","\u0003אלא תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: הזהרו בי מפני בתי\u0004 שלא אתייחד איתה. ומסופר: \u0003אמר ר' טרפון: הזהרו בי מפני כלתי. ליגלג עליו אותו תלמיד\u0004 על שהוא נזהר בדברים אלה שאין מתקבל על הדעת שיחטא בהם. \u0003אמר ר' אבהו משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל: לא היו ימים מועטים עד שנכשל אותו תלמיד\u0004 עצמו \u0003בחמותו.\u0004","שנינו שלדברי שמואל אסור להתייחד \u0003אפילו עם בהמה.\u0004 מסופר: \u0003אביי מכלליה מכולה דברא\u0004 \u0005[היה מוציא אותן,\u0006 את הבהמות, \u0005מכל השדה]\u0006 שהיה נמצא בו. \u0003רב ששת מעבר ליה מצרא\u0004 \u0005[היה מעביר\u0006 את הבהמה לצד השני \u0005של המיצר,\u0006 גדר\u0005].\u0006 \u0003רב חנן מנהרדעא איקלע\u0004 \u0005[הזדמן]\u0006 אצל \u0003רב כהנא\u0004 ב\u0003פום נהרא\u0004\u0005,\u0006 \u0003חזייה דיתיב וקא גרס וקיימא בהמה קמיה\u0004 \u0005[ראה אותו ש\u0006הוא \u0005יושב ולומד ובהמה עומדת לפניו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר לה מר\u0004 \u0005[האם אין אדוני סובר]\u0006 ש\u0003אפילו עם בהמה\u0004 אסור להתייחד? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003לאו אדעתאי\u0004 \u0005[לא היה בדעתי],\u0006 כלומר, לא שמתי לב.","\u0003אמר רבא: מתייחד אדם עם שתי יבמות\u0004 (גיסות) \u0003ועם שתי\u0004 נשים \u0003צרות\u0004 זו לזו, כלומר, שתי נשים של אדם אחד, \u0003עם אשה וחמותה, עם אשה ובת בעלה\u0004 שכיון שכרגיל אלה שונאות זו את זו, כל אחת חוששת שהשניה תספר את מעשיה ונזהרת שלא להתפתות. וכן יכול אדם להתייחד \u0003עם אשה ותינוקת שיודעת טעם ביאה,\u0004 כלומר, שהיא גדולה מספיק שמבינה מה עניינה של ביאה, \u0003ו\u0004היא עדיין קטנה עד ש\u0003אין מוסרת\u0004 את \u0003עצמה לביאה\u0004 שאין בה יצר לפתותה, שהאשה חוששת ממנה שלא תספר את מעשיה.","שנינו במשנה שאם \u0003הגדילו\u0004 הבן או הבת \u0003זה ישן בכסותו וכו'.\u0004 ושואלים: \u0003וכמה\u0004 הוא הזמן שנקראים גדולים לענין זה? \u0003אמר רב אדא בר רב עזא אמר רב אסי: תינוקת בת תשע שנים ויום אחד, תינוק בן שתים עשרה שנה ויום אחד. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003תינוקת\u0004 שאמרנו פה — \u0003בת שתים עשרה שנה ויום אחד, תינוק\u0004 — \u0003בן שלש עשרה\u0004 שנה \u0003ויום אחד. וזה וזה\u0004 לשתי הדעות עיקר שיעורם הוא עד \u0003כדי שיהיו \"שדים נכנו ושערך צמח\"\u0004 (יחזקאל טז, ז), כלומר, תחילת הבגרות.","\u0003אמר רפרם בר פפא אמר רב חסדא: לא שנו\u0004 שיכול לישון עם בתו הקטנה בקירוב בשר \u0003אלא שאינה בושה לעמוד לפניו ערום, אבל בושה לעמוד לפניו ערום\u0004 — \u0003אסור\u0004 כבר לישון עימה בקירוב בשר. \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]\u0006 — \u0003יצר אלבשה\u0004 \u0005[\u0006ה\u0005יצר תפס אותה],\u0006 שלולא היה בה יצר לא היתה מתביישת.","מסופר: \u0003רב אחא בר אבא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב חסדא חתניה\u0004 \u0005[חתנו].\u0006 \u0003שקליה לבת ברתיה אותבוה בכנפיה\u0004 \u0005[לקח את בת בתו\u0006 (שהיתה בתו של רב חסדא) \u0005והושיב אותה בחיקו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003לא סבר לה מר דמקדשא\u0004 \u0005[\u0006וכי \u0005אין אדוני סבור\u0006 שיש לחשוש \u0005שהיא מקודשת\u0006 כבר\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: אם כך הוא \u0003עברת לך אדרב\u0004 \u0005[עברת על\u0006 דברי \u0005רב].\u0006 ש\u0003אמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אלעזר: אסור לאדם שיקדש את בתו כשהיא קטנה, עד שתגדיל ותאמר \"בפלוני אני רוצה\",\u0004 שאם אינו עושה כן יש לחשוש שמא לא תתרצה בחתן שבחרו לה, ותבוא לידי מכשול. אמר לו רב חסדא: \u0003מר נמי עבר ליה אדשמואל\u0004 \u0005[אדוני גם כן עבר על\u0006 דברי \u0005שמואל]\u0006 ש\u0003אמר שמואל: אין משתמשים באשה,\u0004 ואיך אתה מחזיק אותה בחיקך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא כאידך\u0004 \u0005[אני\u0006 \u0003כ\u0004דבריו \u0005האחרים]\u0006 של \u0003שמואל סבירא לי\u0004 \u0005[אני סבור].\u0006 ש\u0003אמר שמואל:\u0004"],["\u0003הכל לשם שמים,\u0004 כלומר, שדבר זה נבחן ונבדק בידי שמים שאם עושה משום חיבת קירבת משפחה וכיוצא בזה, ואין בו צד של חיבת עריות — מותר.","\u0003לא ילמד אדם רווק\u0004 שאין לו אשה \u0003סופרים,\u0004 שלא יהא מלמד תינוקות. \u0003ולא תלמד אשה סופרים,\u0004 שלא תהיה מלמדת תינוקות. \u0003ר' אלעזר אומר: אף מי שאין לו אשה לא ילמד סופרים. ר' יהודה אומר: לא ירעה רווק בהמה, ולא יישנו שני רווקין בטלית אחת\u0004 שמא יבואו לידי עבירה במשכב זכור, \u0003וחכמים מתירים.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שאין מתירים לרווק להיות מלמד תינוקות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום ינוקי\u0004 \u0005[התינוקות]\u0006 שהוא חשוד עליהם במשכב זכור — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמרו לו\u0004 חכמים \u0003לר' יהודה: לא נחשדו ישראל על משכב זכור, ולא על הבהמה! אלא\u0004 הטעם הוא אחר, \u0003רווק\u0004 לא ילמד — \u0003משום אמהתא דינוקי\u0004 \u0005[אמהות של התינוקות]\u0006 שמגיעות מפעם לפעם לבית הספר ועשוי להכשל בהן. וכן \u0003אשה\u0004 לא תלמד — \u0003משום אבהתא דינוקי\u0004 \u0005[אבות התינוקות]\u0006 שהיא עשויה להתייחד איתם.","שנינו במשנה ש\u0003ר' אלעזר אומר אף מי שאין\u0004 לו אשה לא ילמד סופרים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים בבית המדרש\u0005]:\u0006 האם הכוונה בדעת ר' אלעזר היא דווקא \u0003מי שאין לו אשה כלל, או דלמא\u0004 \u0005[שמא]\u0006 מדובר \u0003בש\u0004יש לו אשה אך \u0003אינה שרויה אצלו? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003אף מי שיש לו ואינה שרויה אצלו לא ילמד סופרים,\u0004 משמע שכך היא דעת ר' אלעזר.","שנינו במשנה ש\u0003ר' יהודה אומר לא ירעה\u0004 רווק בהמה ולא יישנו שני רווקים בטלית אחת. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו לו\u0004 חכמים \u0003לר' יהודה: לא נחשדו ישראל על משכב זכור, ולא על\u0004 משכב \u0003הבהמה.\u0004 וזהו הטעם במשנה שחכמים מתירים.","\u0003כל שעסקיו עם הנשים,\u0004 שמלאכתו היא בעיקרה לצרכי נשים, \u0003לא יתיחד עם הנשים,\u0004 מפני שהוא רגיל בהן ביותר ויש לחשוש בו יותר לעבירה. \u0003ולא ילמד אדם את בנו\u0004 מלכתחילה \u0003אומנות הנשים,\u0004 כלומר, מלאכה שבה צריך להיות בעסקי נשים משום אותו חשש. ובאותו ענין \u0003ר' מאיר אומר: לעולם ילמד אדם את בנו אומנות נקיה וקלה, ויתפלל למי שהעושר והנכסים שלו\u0004 שיצליח בה. \u0003ש\u0004בסופו של דבר \u0003אין אומנות שאין בה עניות ועשירות,\u0004 ויכול אדם להתעשר מכל אומנות שבעולם. מכיון \u0003שלא עניות\u0004 באה \u0003מן האומנות, ולא עשירות מן האומנות, אלא הכל לפי זכותו\u0004 של האדם.","\u0003ר' שמעון בן אלעזר אומר: ראית מימיך חיה ועוף שיש להם אומנות? ו\u0004בכל זאת \u0003הן מתפרנסין שלא בצער\u0004 ואינם צריכים לעבוד. \u0003והלא לא נבראו\u0004 כל אלה \u0003אלא לשמשני. ואני\u0004 האדם \u0003נבראתי לשמש את קוני, אינו דין\u0004 (קל וחומר) \u0003שאתפרנס שלא בצער? אלא שהורעתי מעשי\u0004 בחטאי, \u0003וקפחתי\u0004 \u0005[ואיבדתי]\u0006 \u0003את פרנסתי,\u0004 ולכן צריך האדם לעבוד כדי להתפרנס.","\u0003אבא גוריין איש צדיין\u0004 \u0003אומר משום\u0004 (בשם) \u0003אבא גוריא: לא ילמד אדם\u0004 \u0003את בנו\u0004 מלאכת \u0003חמר\u0004 (מוליך חמורים), \u0003גמל\u0004 (מוליך גמלים), \u0003קדר\u0004 (עושה קדירות), \u0003ספן, רועה, וחנוני\u0004 וטעמו של דבר — \u0003שאומנותן אומנות ליסטים,\u0004 שכל אלה יש במקצועם צד של חוסר יושר וחשש גניבה. \u0003ר' יהודה אומר משמו\u0004 של אבא גוריא: \u0003החמרין רובן רשעים,\u0004 מפני שעסקיהם ברמאות, \u0003והגמלין\u0004 העוברים במדבריות שהם מקום סכנה \u0003רובן כשרין,\u0004 ואילו \u0003הספנין\u0004 הפורשים לים \u0003רובן חסידים,\u0004 שמפני שהם עוברים בים במקום סכנה יתירה מגיעים ליראת שמים. \u0003טוב שברופאים לגיהנם, ו\u0004אף \u0003הכשר שבטבחים\u0004 (שוחטים) הוא \u0003שותפו של עמלק.\u0004","\u0003ר' נהוראי אומר: מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה,\u0004 לפי \u0003שאדם אוכל משכרה בעולם הזה, והקרן קיימת לו לעולם הבא, ושאר כל אומנות אינן כן,\u0004 ששכרן הוא רק בעולם הזה. ועוד, \u0003כשאדם בא לידי חולי או לידי זקנה או לידי יסורין, ואינו יכול לעסוק במלאכתו\u0004 — \u0003הרי הוא מת ברעב. אבל התורה אינה כן,\u0004 שיכול לעסוק בה בכל עת, \u0003אלא משמרתו מכל רע\u0004 וחטא \u0003בנערותו, ונותנת לו אחרית ותקוה בזקנותו.\u0004","\u0003בנערותו מהו אומר\u0004 על תלמידי חכמים — \u0003\"וקוי ה' יחליפו כח\"\u0004 (ישעיה מ, לא), \u0003בזקנותו מהו אומר\u0004 — \u0003\"עוד ינובון בשיבה\"\u0004 (תהלים צב, טו). \u0003וכן הוא אומר באברהם אבינו \"ואברהם זקן\u0004 בא בימים \u0003וה' ברך את אברהם בכל\"\u0004 (בראשית כד, א). \u0003מצינו שעשה\u0004 (קיים) \u0003אברהם אבינו את כל התורה כולה עד שלא\u0004 (לפני) \u0003ניתנה, שנאמר: \"עקב אשר שמע אברהם בקלי וישמר משמרתי מצותי חקותי ותורתי\"\u0004 (שם כו, ה), ללמד שכל המצוות מכל סוג (מצוות, חוקות, תורות), כבר קיימן מעצמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל שעסקיו עם הנשים\u0004 — \u0003סורו\u0004 (מנהגו וחברתו) \u0003רע\u0004 וטוב להתרחק ממנוץ \u0003כגון הצורפים, והסריקים\u0004 (סורקי הבגדים), \u0003והנקורות\u0004 (מתקני הריחיים של נשים), \u0003והרוכלין\u0004 שמוכרים תכשיטים ובשמים לנשים, \u0003והגרדיים\u0004 (האורגים), \u0003והספרים והכובסים, והגרע\u0004 (מקיז הדם), \u0003והבלן\u0004 (העובד במרחץ), \u0003והבורסקי\u0004 (המעבד עורות)\u0003.\u0004 כל בעלי המקצועות האלה \u0003אין מעמידים מהם לא מלך ולא כהן גדול. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003לא משום דפסילי\u0004 \u0005[ש\u0006הם \u0005פסולים],\u0006 שאין פסול בעצם מלאכתם, \u0003אלא משום דזיל אומנותיהו\u0004 \u0005[שאומנותם מזולזלת]\u0006 ואף כשיעלו לגדולה יזלזלו בהם הבריות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשרה דברים נאמרו בגרע\u0004 (מקיז הדם): \u0003מהלך על צידו\u0004 בגסות הרוח, \u0003ורוחו גסה\u0004 בגאווה, \u0003ונתלה ויושב,\u0004 שאינו יושב כשאר אדם אלא נשען על משהו מחמת גאווה, \u0003ועינו צרה,\u0004 שהוא קמצן, \u0003ועינו רעה,\u0004 שמקנא באחרים, \u0003אוכל הרבה ומוציא\u0004 רק \u0003קימעא\u0004 (מעט), \u0003וחשוד על העריות ועל הגזל ועל שפיכות דמים\u0004 מתוך מקצועו.","\u0003דרש בר קפרא: לעולם ילמד אדם את בנו אומנות נקיה וקלה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אומנות כזו? \u0003אמר רב יהודה:\u0004"],["\u0003מחטא דתלמיותא\u0004 \u0005[מחט של רקמה],\u0006 שהיא מלאכה נקיה וקלה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: אין לך אומנות שעוברת\u0004 (שנעלמת, בטילה) \u0003מן העולם\u0004 — שיש צורך בכל המלאכות, אבל \u0003אשרי מי שרואה את הוריו באומנות מעולה, אוי לו למי שרואה את הוריו באומנות פגומה\u0004 ולומד מהם. וכן \u0003אי אפשר לעולם בלא\u0004 שיהא בו \u0003בסם\u0004 (עושה בשמים) \u0003ובלא בורסקי\u0004 (מעבד עורות) שאומנותו בדברים מסריחים. \u0003אשרי מי שאומנותו בסם, ואוי לו מי שאומנותו בורסקי.\u0004 וכן \u0003אי אפשר לעולם בלא זכרים ובלא נקבות,\u0004 ששניהם נחוצים לקיום העולם, \u0003אשרי מי שבניו זכרים ואוי לו למי שבניו נקיבות.\u0004 \u0003ר' מאיר אומר: לעולם ילמד אדם לבנו אומנות נקיה וקלה, ויבקש רחמים למי שהעושר והנכסים שלו, שאין עניות מן האומנות ואין עשירות מן האומנות, אלא\u0004 למי הם העשירות והעניות — \u0003למי שהעושר שלו, שנאמר: \"לי הכסף ולי הזהב נאם ה' צבאות\"\u0004 (חגי ב, ח). שנינו במשנה ש\u0003ר' שמעון בן אלעזר אומר אם ראית מימיך\u0004 חיה ועוף שיש להם אומנות וכו'. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: מימי לא ראיתי צבי\u0004 שיהיה \u0003קייץ\u0004 (מייבש תאנים) \u0003וארי\u0004 שיהיה \u0003סבל, ושועל\u0004 שיהיה \u0003חנוני, ו\u0004בכל זאת \u0003הם מתפרנסים שלא בצער\u0004 ואינם צריכים לעבוד. \u0003והם לא נבראו אלא לשמשני,\u0004 לפי שהאדם הוא תכלית הבריאה, \u0003ואני נבראתי לשמש את קוני. מה אלו שלא נבראו אלא לשמשני מתפרנסים שלא בצער, ואני שנבראתי לשמש את קוני\u0004 — \u0003אינו דין שאתפרנס שלא בצער? אלא שהרעותי את מעשי וקיפחתי את פרנסתי, שנאמר: \"עו‍נותיכם הטו\u0004 אלה\u0003\"\u0004 (ירמיה ה, כה). שנינו במשנה ש\u0003ר' נהוראי אומר מניח אני כל אומנות\u0004 שבעולם ואיני מלמד את בני אלא תורה \u0003וכו'. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נהוראי אומר: מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה. שכל אומנות שבעולם אין עומדת לו\u0004 לאדם \u0003אלא בימי ילדותו\u0004 שיש בידו כוח לעבוד, \u0003אבל בימי זקנותו הרי הוא מוטל ברעב. אבל תורה אינה כן, עומדת לו לאדם בעת ילדותו, ונותנת לו אחרית ותקוה בעת זקנותו. בעת ילדותו מהו אומר\u0004 — \u0003\"וקוי ה' יחליפו כח יעלו אבר כנשרים\"\u0004 (ישעיה מ, לא), \u0003בזקנותו מהו אומר\u0004 — \u0003\"עוד ינובון בשיבה דשנים ורעננים יהיו\"\u0004 (תהלים צב, טו).","","","",""]]};
